INSERT INTO `avisos_oficiales` (`id`, `document_id`, `titulo`, `descripcion`, `enlace`, `texto_boton`, `activo`, `created_at`, `updated_at`, `published_at`, `created_by_id`, `updated_by_id`, `locale`) VALUES
	(6, 'pmie6j40nc3zhez8a4ummz14', 'Investigadores del IICASB publican en prestigiosa revista Q2 estudio sobre la flora medicinal en las comunidades Quechua y Aymara del Lago Titicaca', '[{"type": "paragraph", "children": [{"text": "El Instituto de Investigación en Ciencias Ambientales, Salud y Biodiversidad (IICASB) comparte con orgullo el artículo científico “Ethnobotanical evaluation of medicinal flora in Quechua and Aymara communities of the Capachica and Chucuito peninsulas, Lake Titicaca, Peru”, publicado en la revista indexada Phytomedicine Plus. Este estudio evalúa el valor etnobotánico y el conocimiento tradicional de las plantas medicinales en las penínsulas de Capachica y Chucuito, salvaguardando el patrimonio biocultural de la región Puno.", "type": "text"}]}]', 'https://web.vriunap.pe/noticias/80', 'Ver Noticia', 0, '2026-06-18 19:13:22.987000', '2026-06-30 12:28:52.650000', NULL, 1, 1, NULL),
	(13, 'pmie6j40nc3zhez8a4ummz14', 'Investigadores del IICASB publican en prestigiosa revista Q2 estudio sobre la flora medicinal en las comunidades Quechua y Aymara del Lago Titicaca', '[{"type": "paragraph", "children": [{"text": "El Instituto de Investigación en Ciencias Ambientales, Salud y Biodiversidad (IICASB) comparte con orgullo el artículo científico “Ethnobotanical evaluation of medicinal flora in Quechua and Aymara communities of the Capachica and Chucuito peninsulas, Lake Titicaca, Peru”, publicado en la revista indexada Phytomedicine Plus. Este estudio evalúa el valor etnobotánico y el conocimiento tradicional de las plantas medicinales en las penínsulas de Capachica y Chucuito, salvaguardando el patrimonio biocultural de la región Puno.", "type": "text"}]}]', 'https://web.vriunap.pe/noticias/80', 'Ver Noticia', 0, '2026-06-18 19:13:22.987000', '2026-06-30 12:28:52.650000', '2026-06-30 12:28:52.679000', 1, 1, NULL),
	(14, 'wrn94f8duu6uy2ipwwrwdzup', 'JULIO ES EL MES DE LA INVESTIGACIÓN', '[{"type": "paragraph", "children": [{"text": "Participa en nuestras actividades académicas y científicas.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "5 GRANDES EVENTOS PARA IMPULSAR TU TALENTO", "type": "text"}]}]', 'https://web.vriunap.pe/convocatorias', 'Ver convocatorias', 0, '2026-07-01 17:23:11.547000', '2026-07-30 18:39:23.283000', NULL, 1, 1, NULL),
	(16, 'wrn94f8duu6uy2ipwwrwdzup', 'JULIO ES EL MES DE LA INVESTIGACIÓN', '[{"type": "paragraph", "children": [{"text": "Participa en nuestras actividades académicas y científicas.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "5 GRANDES EVENTOS PARA IMPULSAR TU TALENTO", "type": "text"}]}]', 'https://web.vriunap.pe/convocatorias', 'Ver convocatorias', 0, '2026-07-01 17:23:11.547000', '2026-07-30 18:39:23.283000', '2026-07-30 18:39:23.307000', 1, 1, NULL),
	(17, 'aaqz19dpu2d4wybg7p89sf16', 'Resultados de los 50 semilleros de investigación ganadores del Concurso de Financiamiento de Semilleros 2026', '[{"type": "paragraph", "children": [{"text": "La Universidad Nacional del Altiplano (UNA-Puno) dio a conocer los resultados oficiales del Concurso de Semilleros de Investigación 2026, en el que participaron 75 semilleros de 21 escuelas profesionales. Tras la evaluación por puntaje, 50 semilleros fueron declarados ganadores mediante un sistema de distribución proporcional por escuela profesional, garantizando al menos un cupo por cada una.", "type": "text"}]}]', 'https://web.vriunap.pe/noticias/86', 'Ver Resultados', 0, '2026-07-30 18:41:10.592000', '2026-08-07 12:57:44.730000', NULL, 1, 1, NULL),
	(20, 'aaqz19dpu2d4wybg7p89sf16', 'Resultados de los 50 semilleros de investigación ganadores del Concurso de Financiamiento de Semilleros 2026', '[{"type": "paragraph", "children": [{"text": "La Universidad Nacional del Altiplano (UNA-Puno) dio a conocer los resultados oficiales del Concurso de Semilleros de Investigación 2026, en el que participaron 75 semilleros de 21 escuelas profesionales. Tras la evaluación por puntaje, 50 semilleros fueron declarados ganadores mediante un sistema de distribución proporcional por escuela profesional, garantizando al menos un cupo por cada una.", "type": "text"}]}]', 'https://web.vriunap.pe/noticias/86', 'Ver Resultados', 0, '2026-07-30 18:41:10.592000', '2026-08-07 12:57:44.730000', '2026-08-07 12:57:44.752000', 1, 1, NULL);
