	(8, 'u95tmhdapebsq548fqesjizc', 'Convocatoria Extraordinaria 2026', '[{"type": "paragraph", "children": [{"text": "El VRI convoca a docentes ordinarios de la UNA Puno para incorporarse al Régimen Especial de Docente Investigador.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"bold": true, "text": "REQUISITOS CLAVE:", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "- Ser docente ordinario (Principal, Asociado o Auxiliar)", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "- Clasificación RENACYT activa (mín. Nivel VII)", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "- Grado de Maestro o Doctor en SUNEDU.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "- Afiliación vigente a la UNA Puno.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "- 1 publicación citable en los últimos 2 años (Scopus/WoS).", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "- Liderar o integrar un grupo/semillero de investigación.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "🗓️", "type": "text"}, {"bold": true, "text": " CRONOGRAMA:", "type": "text"}, {"text": " Postulación virtual: Del 15 al 30 de abril.", "type": "text"}]}, {"type": "paragraph", "children": [{"bold": true, "text": "Resultados", "type": "text"}, {"text": ": 06 de mayo.", "type": "text"}]}]', 'Investigación', 'Cerrada', '2026-04-27 16:12:38.074000', '2026-08-05 16:37:17.720000', NULL, 7, 7, NULL, '2026-04-30 05:00:00.000000', 'https://forms.gle/yzCiwhtB72pbtRgCA', 'https://vriunap.pe/reglamentos', '#UNA_Puno_Investiga', 'Instituto de Investigacion', NULL),
