	(93, 'p85ll37xnrqj9l411a1jnjk0', 'Convocatoria abierta para el Programa de Preincubación', '[{"type": "paragraph", "children": [{"text": "📅 Cierre de inscripciones: 8 de junio", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "Estamos felices de anunciar que ya se encuentra abierta la convocatoria para nuestro Programa de Preincubación. Los participantes accederán a dos semanas de capacitación donde podrán llevar su idea de negocio a un siguiente nivel.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "✅ Los participantes también tendrán la oportunidad de participar en una feria donde podrán exponer sus ideas y vender sus productos", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "🏆 Grandes premios para los primeros lugares.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "🔗 Inscríbete aquí: ", "type": "text"}, {"url": "https://incunalab.com/preincubacion", "type": "link", "children": [{"text": "https://incunalab.com/preincubacion", "type": "text"}]}, {"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "💡 Si tienes una idea, no puedes perder esta oportunidad.", "type": "text"}]}]', 'Convocatoria', 'Cerrada', '2026-06-16 18:09:44.977000', '2026-08-05 13:54:51.373000', '2026-08-05 13:54:51.425000', 1, 7, NULL, '2026-06-03 05:00:00.000000', 'https://incunalab.com/preincubacion', NULL, NULL, 'Direccion de Incubadoras de Empresas', '2026-06-08 05:00:00.000000'),
	(94, 'aybuymun738ovu1ugl7cz0zr', 'III Convocatoria para Financiamiento de Semilleros de Investigación', '[{"type": "paragraph", "children": [{"text": "📢", "type": "text"}, {"text": " ¡Impulsando la investigación en la Universidad Nacional del Altiplano!", "type": "text", "italic": true}, {"text": " 🔬🚀", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "La Universidad Nacional del Altiplano, a través del Instituto de Investigación y el Vicerrectorado de Investigación, invita a la comunidad universitaria a participar en la:", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "🔹", "type": "text"}, {"bold": true, "text": " III Convocatoria para Financiamiento de Semilleros de Investigación", "type": "text", "italic": true}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "Esta iniciativa busca fortalecer el ecosistema de investigación y desarrollo, promoviendo proyectos innovadores con alto potencial de impacto en las áreas de Ciencias Sociales, Ingenierías y Biomédicas.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "📌", "type": "text"}, {"bold": true, "text": " Cronograma", "type": "text", "italic": true}]}, {"type": "paragraph", "children": [{"text": "✅ Inscripción de proyectos: del 01 al 12 de junio de 2026 (Ampliación hasta el 17 de junio de 2026)", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "✅ Evaluación de proyectos: del 13 al 19 de junio de 2026", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "✅ Publicación de resultados: 23 de junio de 2026", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "🎯", "type": "text"}, {"bold": true, "text": " Beneficios:", "type": "text", "italic": true}]}, {"type": "paragraph", "children": [{"text": "🌱 Financiamiento para 50 Semilleros de Investigación", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "📖 Revisa las bases de la convocatoria y presenta tu propuesta. Esta es una oportunidad para convertir tus ideas en proyectos que contribuyan al desarrollo científico, tecnológico y social de nuestra región y del país.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"bold": true, "text": "", "type": "text", "italic": true}, {"url": "https://docs.google.com/document/d/16Xt_nOIn-kj25r5T64YfAztrg3_cny98/edit?pli=1#heading=h.gyeul42funpa", "type": "link", "children": [{"bold": true, "text": "BASES", "type": "text", "italic": true}]}, {"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}]', 'Concurso', 'Cerrada', '2026-06-02 16:07:54.482000', '2026-08-05 13:56:12.788000', '2026-08-05 13:56:12.820000', 7, 7, NULL, '2026-06-01 05:00:00.000000', 'https://dii.unap.edu.pe/', 'https://dii.unap.edu.pe/bases_semilleros%20V3.pdf', NULL, 'Instituto de Investigacion', '2026-06-17 05:00:00.000000'),
