INSERT INTO `eventos` (`id`, `document_id`, `titulo`, `descripcion`, `fecha`, `link_registro`, `link_interes`, `tipo`, `estado`, `etiquetas`, `created_at`, `updated_at`, `published_at`, `created_by_id`, `updated_by_id`, `locale`, `direccion`, `fecha_culminacion`) VALUES
	(11, 'bszm3nomz484jq6pa632uhi7', 'Cuarto Seminario de Pasantías – 2025-II', '[{"type": "paragraph", "children": [{"text": "El ", "type": "text"}, {"bold": true, "text": "Vicerrectorado de Investigación (VRI)", "type": "text"}, {"text": " presenta la Exposición de experiencias de docentes de la pasantía semestral 2025-II", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "🗓 ", "type": "text"}, {"bold": true, "text": "23 de Abril", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "⏰ ", "type": "text"}, {"bold": true, "text": "9:30 a.m.", "type": "text"}, {"text": " (hora exacta)", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "📍 ", "type": "text"}, {"bold": true, "text": "Auditorio Magno", "type": "text"}, {"text": " – UNA Puno", "type": "text"}]}]', '2026-04-23 14:30:00.000000', NULL, NULL, NULL, 'Finalizado', NULL, '2026-04-27 15:23:20.272000', '2026-08-07 14:04:24.213000', NULL, 7, 1, NULL, 'Direccion de Innovacion y Transferencia Tecnologica', '2026-04-23 05:00:00.000000');
INSERT INTO `eventos` (`id`, `document_id`, `titulo`, `descripcion`, `fecha`, `link_registro`, `link_interes`, `tipo`, `estado`, `etiquetas`, `created_at`, `updated_at`, `published_at`, `created_by_id`, `updated_by_id`, `locale`, `direccion`, `fecha_culminacion`) VALUES
	(16, 'eferlq2wuwc424ov1xfxrnwx', 'Emprendelaria 2025 ', '[{"type": "paragraph", "children": [{"text": "Este 22 y 23 de diciembre, la magia de la Navidad se encuentra con el talento emprendedor de Puno.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "Vive dos días llenos de creatividad, regalos únicos, arte, cultura y mucho movimiento en nuestra Feria de Emprendimientos.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "🎶 Música en vivo", "type": "text", "italic": true}]}, {"type": "paragraph", "children": [{"text": "🎨 Arte local", "type": "text", "italic": true}]}, {"type": "paragraph", "children": [{"text": "🎁 Productos especiales para regalar", "type": "text", "italic": true}]}, {"type": "paragraph", "children": [{"text": "🚀 Emprendimientos que inspiran", "type": "text", "italic": true}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "📍 ", "type": "text"}, {"bold": true, "text": "Educación Continua – Av. El Sol 329", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"bold": true, "text": "🎟 Ingreso libre para todos", "type": "text", "italic": true}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "Porque los mejores regalos… los crean nuestros emprendedores.", "type": "text"}]}]', '2025-12-22 05:00:00.000000', NULL, NULL, NULL, 'Finalizado', '#Emprendelaria2025 #NavidadEmprendedora #EmprendimientoLocal #INCUNALAB', '2026-04-27 16:38:22.736000', '2026-08-07 14:05:27.588000', NULL, 7, 1, NULL, 'Direccion de Incubadoras de Empresas', '2025-12-23 05:00:00.000000'),
	(18, 'ztojuzjko21h4buglmp1qw0p', 'I Expo Investigación Estudiantil', '[{"type": "paragraph", "children": [{"bold": true, "text": "¡Estudiantes, esta es su oportunidad para brillar!", "type": "text"}, {"text": " 🌟", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "🎓 El Vicerrectorado de Investigación de la Universidad Nacional del Altiplano los invita a participar en la I Expo Investigación Estudiantil.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "🗓", "type": "text"}, {"bold": true, "text": " Fecha: ", "type": "text"}, {"text": "19 de diciembre", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "📍 ", "type": "text"}, {"bold": true, "text": "Lugar:", "type": "text"}, {"text": " Campus Universitario", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "🔔 ", "type": "text"}, {"bold": true, "text": "¡Las inscripciones están abiertas hasta el 3 de diciembre! ", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "No pierdas la oportunidad de compartir tu trabajo y aprender de los demás. ¡Haz que tu investigación se vea!", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "🎯 Revisa las bases e inscríbete en ", "type": "text"}, {"bold": true, "text": "https://vriunap.pe/cursos/", "type": "text", "italic": true}]}, {"type": "paragraph", "children": [{"text": " o escanea el QR para más información.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"bold": true, "text": "Organiza: Instituto de Investigación – VRI | Universidad Nacional del Altiplano", "type": "text", "italic": true}]}]', '2025-12-19 05:00:00.000000', 'https://vriunap.pe/cursos/', 'https://vriunap.pe/cursos/', 'Investigación', 'Finalizado', '#investigaciónestudiantil #vriunap #UNAP #innovación #investigacióncientífica', '2026-04-27 17:10:45.689000', '2026-08-07 14:05:55.501000', NULL, 7, 1, NULL, 'Instituto de Investigacion', NULL),
	(20, 'qi3cf5o16333vjacb8fx8vr5', 'Mi Proyecto de Tesis en un Póster ', '[{"type": "paragraph", "children": [{"bold": true, "text": "Tu investigación merece ser vista. ", "type": "text"}, {"text": "💡✨", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "El Instituto de Investigación de la UNA Puno te invita a participar en ", "type": "text"}, {"bold": true, "text": "“Mi Proyecto de Tesis en un Póster”", "type": "text", "italic": true}, {"text": ", una oportunidad para mostrar tu trabajo y destacar tu talento.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"bold": true, "text": "📝 Inscripciones abiertas hasta el 17 de noviembre", "type": "text", "italic": true}]}, {"type": "paragraph", "children": [{"bold": true, "text": "🏆 Premiación a los tres mejores proyectos", "type": "text", "italic": true}]}, {"type": "paragraph", "children": [{"bold": true, "text": "📌 Áreas: Ingenierías, Biomédicas y Sociales", "type": "text", "italic": true}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "Ingresa a 👉", "type": "text"}, {"bold": true, "text": " ", "type": "text", "italic": true}, {"url": "https://vriunap.pe/cursos/", "type": "link", "children": [{"bold": true, "text": "vriunap.pe/cursos", "type": "text", "italic": true}]}, {"text": " y únete.", "type": "text"}]}]', '2025-11-17 05:00:00.000000', 'vriunap.pe/cursos', 'vriunap.pe/cursos', 'Investigación', 'Finalizado', NULL, '2026-04-27 17:15:32.410000', '2026-08-07 14:07:18.430000', NULL, 7, 1, NULL, 'Instituto de Investigacion', NULL),
