	(35, 'mfl6smb5cabypehwcg4gclqe', 'III Jornada de Investigación UNA Puno', '[{"type": "paragraph", "children": [{"text": "🚨 ¡", "type": "text"}, {"bold": true, "text": "HOY ES EL ÚLTIMO DÍA", "type": "text"}, {"text": "! 🚨", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "No dejes pasar tu oportunidad de participar en la III Jornada de Investigación – UNA Puno.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"bold": true, "text": "🗓 Del 15 al 19 de diciembre:", "type": "text", "italic": true}]}, {"type": "paragraph", "children": [{"text": "📅 ", "type": "text"}, {"bold": true, "text": "15-16 dic", "type": "text"}, {"text": ":", "type": "text"}, {"bold": true, "text": " III Congreso de Iniciación Científica", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "📅 ", "type": "text"}, {"bold": true, "text": "17 dic", "type": "text"}, {"text": ":", "type": "text"}, {"bold": true, "text": " Concurso “Mi Proyecto de Tesis en un Póster”", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "📅 ", "type": "text"}, {"bold": true, "text": "18 dic: Concurso Póster Científico UNA Puno", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "📅 ", "type": "text"}, {"bold": true, "text": "19 dic: I Expo Investigación Estudiantil", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "🏆 Premios para los mejores proyectos, 📜 certificación de asistencia y 💡 la chance de compartir tus ideas con toda la comunidad estudiantil.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "📝 Inscríbete AHORA antes de que cierren las inscripciones.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "📲 Escanea el QR y sé parte del cambio con tus ideas.", "type": "text"}]}]', '2025-11-19 05:00:00.000000', 'https://vriunap.pe/cursos/', NULL, NULL, 'Proximamente', NULL, '2026-04-27 20:38:10.276000', '2026-08-07 14:06:54.604000', NULL, 7, 1, NULL, 'Instituto de Investigacion', NULL),
	(43, 'snku5bf4q0zq5eox0y04ewsq', 'Capacitación de Desarrollo del Proyecto de Borrador de Tesis de Pregrado en la Plataforma PGI', '[{"type": "paragraph", "children": [{"bold": true, "text": "Convocatoria a Capacitación: Desarrollo del Proyecto y Borrador de Tesis de Pregrado en la Plataforma PGI ", "type": "text"}, {"text": "🔹", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "La Universidad Nacional del Altiplano, a través del Vicerrectorado de Investigación, se complace en invitar a todos los estudiantes de pregrado a la capacitación sobre el desarrollo de proyectos y la elaboración del borrador de tesis, utilizando la Plataforma de Gestión de la Investigación (PGI).", "type": "text"}]}, {"type": "paragraph", "children": [{"bold": true, "text": "", "type": "text", "italic": true}]}, {"type": "paragraph", "children": [{"bold": true, "text": "📅 Fecha: ", "type": "text", "italic": true}, {"text": "Viernes, 07 de noviembre", "type": "text", "italic": true}]}, {"type": "paragraph", "children": [{"bold": true, "text": "⏰ Hora: ", "type": "text", "italic": true}, {"text": "9:00 A.M.", "type": "text", "italic": true}]}, {"type": "paragraph", "children": [{"bold": true, "text": "📍 Modalidad: ", "type": "text", "italic": true}, {"text": "Virtual, a través de Google Meet", "type": "text", "italic": true}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "Esta capacitación tiene como objetivo proporcionar herramientas y orientación para el uso efectivo de la plataforma PGI en la elaboración de proyectos de investigación y la estructuración del borrador de tesis.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "🔗 Para participar, acceda al evento virtual a través del siguiente QR o enlace: ", "type": "text"}, {"url": "https://meet.google.com/qzu-mtht-xup", "type": "link", "children": [{"bold": true, "text": "https://meet.google.com/qzu-mtht-xup", "type": "text", "italic": true}]}, {"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"bold": true, "text": "Esperamos contar con su participación.", "type": "text", "italic": true}]}]', '2025-11-07 14:00:00.000000', NULL, NULL, 'Capacitación', 'Finalizado', '#Capacitación #DesarrolloDeTesis #Investigación #PlataformaPGI #VicerrectoradoDeInvestigación #UNAP', '2026-04-28 14:06:56.784000', '2026-08-07 14:08:10.784000', NULL, 7, 1, NULL, 'Instituto de Investigacion', '2025-11-07 05:00:00.000000'),
	(46, 'k6vzwkjrwhrn7kxueqqnq75k', 'Presentación de la nueva Plataforma de Gestión de la Investigación ', '[{"type": "paragraph", "children": [{"text": "📢", "type": "text"}, {"bold": true, "text": " Presentamos la nueva Plataforma de Gestión de la Investigación", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "Una herramienta desarrollada para fortalecer y optimizar los procesos de investigación en nuestra universidad.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "🗓", "type": "text"}, {"bold": true, "text": " Lanzamiento oficial: ", "type": "text"}, {"text": "21 de octubre", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "🕚", "type": "text"}, {"bold": true, "text": " Hora: ", "type": "text"}, {"text": "11:00 a. m.", "type": "text"}]}, {"type": "paragraph", "children": [{"bold": true, "text": "📍 Lugar:", "type": "text"}, {"text": " Auditorio de la Escuela Profesional de Arquitectura y Urbanismo", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"bold": true, "text": "Organiza:", "type": "text"}]}, {"type": "paragraph", "children": [{"bold": true, "text": "🧩 Instituto de Investigación", "type": "text"}]}, {"type": "paragraph", "children": [{"bold": true, "text": "💡 Vicerrectorado de Investigación", "type": "text"}]}]', '2026-04-21 16:00:00.000000', NULL, NULL, 'Investigación', 'Finalizado', '#InvestigaciónUNA #Innovación #VRI #UNA #gestióndelconocimiento #PGI', '2026-04-28 14:48:27.908000', '2026-08-06 14:47:50.086000', NULL, 7, 7, NULL, 'Instituto de Investigacion', NULL),
	(48, 'ksnbg1uysl571ol7ipnp6owu', 'Proceso Editorial de una Revista Científica para Indizarse en una Base de Datos', '[{"type": "paragraph", "children": [{"text": "📚", "type": "text"}, {"bold": true, "text": "✨ ¿Quieres que tu revista científica sea indizada en una base de datos?", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "El Instituto de Investigación te invita a la capacitación:", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "🔹", "type": "text"}, {"bold": true, "text": " Proceso editorial de una revista científica para indizarse en una base de datos", "type": "text", "italic": true}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "👨‍🏫", "type": "text"}, {"bold": true, "text": " Ponente", "type": "text"}, {"text": ": Ing. Fernando Ricardo Ardito Saenz", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "📅", "type": "text"}, {"bold": true, "text": " Fecha:", "type": "text"}, {"text": " 14 de octubre", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "⏰ ", "type": "text"}, {"bold": true, "text": "Horario", "type": "text"}, {"text": ": 3:00 – 6:00 p.m.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "📍 ", "type": "text"}, {"bold": true, "text": "Lugar:", "type": "text"}, {"text": " Auditorio de Ciencias Contables UNA-Puno (Pabellón antiguo)", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"bold": true, "text": "✅ Certificación con 100% de asistencia.", "type": "text"}]}, {"type": "paragraph", "children": [{"bold": true, "text": "✅ Ingreso libre.", "type": "text"}]}]', '2025-10-14 20:00:00.000000', NULL, NULL, 'Investigación', 'Finalizado', '#UNA #UNA_Investigación', '2026-04-28 15:04:13.836000', '2026-08-07 14:08:43.638000', NULL, 7, 1, NULL, 'Instituto de Investigacion', NULL),
	(50, 'o0piv2gga9bpi8tvfhsg4zvk', ' Webinars "YachAI Lab"', '[{"type": "paragraph", "children": [{"bold": true, "text": "Inscríbete en nuestro ciclo de Webinars \\"YachAI Lab\\"", "type": "text"}, {"text": " 🚀", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "Te invitamos a participar en nuestros webinars, un espacio donde la experiencia de INCUNALAB se fusiona con el poder la Inteligencia Artificial para crear líderes tecnológicos de la nueva economía. 🌎", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "Potencia tu conocimiento con herramientas reales, estrategias probadas y casos de éxito latinoamericano. ✨", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"bold": true, "text": "📌Inicio: 06 de Mayo", "type": "text", "italic": true}]}, {"type": "paragraph", "children": [{"bold": true, "text": "🖥️ Modalidad virtual", "type": "text", "italic": true}]}, {"type": "paragraph", "children": [{"bold": true, "text": "🏅 Certificación internacional", "type": "text", "italic": true}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "📍 Inscripciones gratuitas en:", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text", "italic": true}, {"url": "https://incunalab.com/yachai", "type": "link", "children": [{"bold": true, "text": "https://incunalab.com/yachai", "type": "text", "italic": true}]}, {"text": "", "type": "text"}]}]', '2026-05-06 05:00:00.000000', NULL, NULL, NULL, 'Finalizado', NULL, '2026-05-05 14:25:52.594000', '2026-08-07 14:03:51.867000', NULL, 7, 1, NULL, 'Direccion de Incubadoras de Empresas', '2026-05-06 05:00:00.000000'),
	(52, 'it3mc30gfq9r0n8ub93ubiay', 'III Congreso Internacional de Investigación', '[{"type": "paragraph", "children": [{"bold": true, "text": "🔬✨ La ciencia nos une", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "Desde el Vicerrectorado de Investigación de la Universidad Nacional del Altiplano de Puno, invitamos a la comunidad académica y al público en general al III Congreso Internacional de Investigación.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"bold": true, "text": "🗓️ 13 al 15 de octubre de 2025", "type": "text", "italic": true}]}, {"type": "paragraph", "children": [{"bold": true, "text": "📍 Modalidad presencial – UNA Puno", "type": "text", "italic": true}]}, {"type": "paragraph", "children": [{"bold": true, "text": "✅ Se entregará certificación", "type": "text", "italic": true}]}, {"type": "paragraph", "children": [{"bold": true, "text": "📑 Inscripciones abiertas hasta el 10 de octubre", "type": "text", "italic": true}]}, {"type": "paragraph", "children": [{"bold": true, "text": "📑", "type": "text", "italic": true}, {"url": "https://vriunap.pe/cursos/", "type": "link", "children": [{"bold": true, "text": " vriunap.pe/cursos", "type": "text", "italic": true}]}, {"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "👉 ¡Sé parte de este gran encuentro académico con ponentes de Perú, Brasil y Costa Rica! ", "type": "text"}]}]', '2025-10-13 05:00:00.000000', 'https://vriunap.pe/cursos/', NULL, 'Investigación', 'Finalizado', NULL, '2026-05-05 14:29:13.005000', '2026-08-07 14:09:11.418000', NULL, 7, 1, NULL, 'Instituto de Investigacion', NULL),
	(78, 'nqaw2b1p0ajmjqjfpydkdyss', '¡Participa en el IV Congreso Nacional de Semilleros de Investigación – CONASEIN 2026!', '[{"type": "paragraph", "children": [{"text": "Con el objetivo de impulsar la generación de conocimiento, la innovación y el fortalecimiento del ecosistema científico y tecnológico del país, el CONCYTEC, la Universidad Católica de Santa María (UCSM) y el Comité Pro Mujer en CTI del CONCYTEC organizan el IV Congreso Nacional de Semilleros de Investigación (CONASEIN 2026), que se llevará a cabo en la ciudad de Arequipa.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "🌟 Bajo el lema:", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "“Mentes jóvenes para el desarrollo científico y tecnológico de un Perú sostenible e innovador”, este importante encuentro busca consolidar la investigación formativa como un pilar fundamental en la formación universitaria, promoviendo la innovación, el pensamiento crítico y el compromiso con el desarrollo del país.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "👨‍🎓 ¿Quiénes pueden participar?", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "✔️ Estudiantes universitarios integrantes de semilleros, círculos o grupos de investigación.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "✔️ Egresados hasta su segundo año de culminados sus estudios.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "✔️ Todos los equipos deberán participar junto a sus docentes asesores.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "📚 Áreas de participación", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "🔹 Ciencias Naturales", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "🔹 Ingeniería y Tecnología", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "🔹 Ciencias Médicas y de la Salud", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "🔹 Ciencias Agrícolas", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "🔹 Ciencias Sociales y Humanidades", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "📅 Cronograma", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "📝 Inscripción: del 14 de mayo al 30 de junio de 2026", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "🔍 Evaluación de proyectos: del 01 de julio al 03 de agosto de 2026", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "📢 Publicación de resultados: del 04 al 07 de agosto de 2026", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "🎓 Evento presencial en Arequipa: del 30 de septiembre al 02 de octubre de 2026", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "💻 Inscripción virtual", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "Los representantes de cada equipo podrán registrar sus proyectos a través de la plataforma oficial:", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}, {"url": "https://congresos.ucsm.edu.pe/CONASEIN2026/", "type": "link", "children": [{"text": "https://congresos.ucsm.edu.pe/CONASEIN2026/", "type": "text"}]}, {"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "📧 Consultas:", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "conasein.2026@ucsm.edu.pe", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "🕘 Horario de atención: 09:00 a 13:00 h y 14:00 a 16:00 h.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "🚀 ¡Es momento de presentar tus ideas, compartir tus investigaciones y formar parte de una comunidad comprometida con el futuro científico y tecnológico del Perú!", "type": "text"}]}]', '2026-06-05 05:00:00.000000', 'https://congresos.ucsm.edu.pe/CONASEIN2026/', NULL, NULL, 'En curso', NULL, '2026-06-16 18:12:53.261000', '2026-08-06 14:45:43.775000', NULL, 1, 7, NULL, 'Instituto de Investigacion', '2026-06-30 05:00:00.000000'),
