	(81, 'k6vzwkjrwhrn7kxueqqnq75k', 'Presentación de la nueva Plataforma de Gestión de la Investigación ', '[{"type": "paragraph", "children": [{"text": "📢", "type": "text"}, {"bold": true, "text": " Presentamos la nueva Plataforma de Gestión de la Investigación", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "Una herramienta desarrollada para fortalecer y optimizar los procesos de investigación en nuestra universidad.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "🗓", "type": "text"}, {"bold": true, "text": " Lanzamiento oficial: ", "type": "text"}, {"text": "21 de octubre", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "🕚", "type": "text"}, {"bold": true, "text": " Hora: ", "type": "text"}, {"text": "11:00 a. m.", "type": "text"}]}, {"type": "paragraph", "children": [{"bold": true, "text": "📍 Lugar:", "type": "text"}, {"text": " Auditorio de la Escuela Profesional de Arquitectura y Urbanismo", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"bold": true, "text": "Organiza:", "type": "text"}]}, {"type": "paragraph", "children": [{"bold": true, "text": "🧩 Instituto de Investigación", "type": "text"}]}, {"type": "paragraph", "children": [{"bold": true, "text": "💡 Vicerrectorado de Investigación", "type": "text"}]}]', '2026-04-21 16:00:00.000000', NULL, NULL, 'Investigación', 'Finalizado', '#InvestigaciónUNA #Innovación #VRI #UNA #gestióndelconocimiento #PGI', '2026-04-28 14:48:27.908000', '2026-08-06 14:47:50.086000', '2026-08-06 14:47:50.118000', 7, 7, NULL, 'Instituto de Investigacion', NULL),
