	(83, 'bszm3nomz484jq6pa632uhi7', 'Cuarto Seminario de Pasantías – 2025-II', '[{"type": "paragraph", "children": [{"text": "El ", "type": "text"}, {"bold": true, "text": "Vicerrectorado de Investigación (VRI)", "type": "text"}, {"text": " presenta la Exposición de experiencias de docentes de la pasantía semestral 2025-II", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "🗓 ", "type": "text"}, {"bold": true, "text": "23 de Abril", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "⏰ ", "type": "text"}, {"bold": true, "text": "9:30 a.m.", "type": "text"}, {"text": " (hora exacta)", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "📍 ", "type": "text"}, {"bold": true, "text": "Auditorio Magno", "type": "text"}, {"text": " – UNA Puno", "type": "text"}]}]', '2026-04-23 14:30:00.000000', NULL, NULL, NULL, 'Finalizado', NULL, '2026-04-27 15:23:20.272000', '2026-08-07 14:04:24.213000', '2026-08-07 14:04:24.238000', 7, 1, NULL, 'Direccion de Innovacion y Transferencia Tecnologica', '2026-04-23 05:00:00.000000'),
	(84, 'q1s7eo471man9s0mdd03lm45', 'Emprendelaria 2025', '[{"type": "paragraph", "children": [{"bold": true, "text": "El festival más grande de la región de Puno", "type": "text", "italic": true}, {"text": " ", "type": "text"}, {"text": "abre sus puertas a la creatividad, innovación y sabor, en su tercera edición llega con manos mágicas y mucho gusto. ", "type": "text", "italic": true}, {"text": "🎊", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "Este 12, 13 y 14 de diciembre", "type": "text", "italic": true}, {"text": ", el Salón de Eventos de la UNA Puno se llenará de energía emprendedora con tres espacios imperdibles:", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "🍴 ", "type": "text"}, {"bold": true, "text": "Con Mucho Gusto", "type": "text"}, {"text": ": Festival gastronómico con los mejores sabores del país.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "👐", "type": "text"}, {"bold": true, "text": " Manos Mágicas: ", "type": "text"}, {"text": "Feria artesanal que celebra la diversidad artística de nuestra cultura.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "🚀", "type": "text"}, {"bold": true, "text": " Feria de Emprendimiento UNA: ", "type": "text"}, {"text": "Los mejores emprendedores de la comunidad universitaria.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "🕘 ", "type": "text"}, {"bold": true, "text": "Desde las 9:00 a.m. ", "type": "text"}, {"text": "prepárate para vivir tres días de experiencias gastronómicas, conciertos y mucha innovación empresarial.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "Postula tu emprendimiento hasta el 7 de noviembre en el siguiente enlace:", "type": "text"}]}, {"type": "paragraph", "children": [{"bold": true, "text": "", "type": "text", "italic": true}, {"url": "https://incunalab.com/emprendelaria2025", "type": "link", "children": [{"bold": true, "text": "Emprendelaria2025", "type": "text", "italic": true}]}, {"text": "", "type": "text"}]}]', '2025-12-12 14:00:00.000000', 'https://incunalab.com/emprendelaria2025', 'https://incunalab.com/emprendelaria2025', NULL, 'Finalizado', '#Emprendelaria2025 #emprendimiento #innovación #ManosMágicas #ConMuchoGusto #FestivalDeEmprendimiento', '2026-04-27 17:48:31.696000', '2026-08-07 14:05:04.077000', '2026-08-07 14:05:04.106000', 7, 1, NULL, 'Direccion de Incubadoras de Empresas', '2025-12-14 05:00:00.000000'),
	(85, 'eferlq2wuwc424ov1xfxrnwx', 'Emprendelaria 2025 ', '[{"type": "paragraph", "children": [{"text": "Este 22 y 23 de diciembre, la magia de la Navidad se encuentra con el talento emprendedor de Puno.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "Vive dos días llenos de creatividad, regalos únicos, arte, cultura y mucho movimiento en nuestra Feria de Emprendimientos.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "🎶 Música en vivo", "type": "text", "italic": true}]}, {"type": "paragraph", "children": [{"text": "🎨 Arte local", "type": "text", "italic": true}]}, {"type": "paragraph", "children": [{"text": "🎁 Productos especiales para regalar", "type": "text", "italic": true}]}, {"type": "paragraph", "children": [{"text": "🚀 Emprendimientos que inspiran", "type": "text", "italic": true}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "📍 ", "type": "text"}, {"bold": true, "text": "Educación Continua – Av. El Sol 329", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"bold": true, "text": "🎟 Ingreso libre para todos", "type": "text", "italic": true}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "Porque los mejores regalos… los crean nuestros emprendedores.", "type": "text"}]}]', '2025-12-22 05:00:00.000000', NULL, NULL, NULL, 'Finalizado', '#Emprendelaria2025 #NavidadEmprendedora #EmprendimientoLocal #INCUNALAB', '2026-04-27 16:38:22.736000', '2026-08-07 14:05:27.588000', '2026-08-07 14:05:27.612000', 7, 1, NULL, 'Direccion de Incubadoras de Empresas', '2025-12-23 05:00:00.000000'),
	(86, 'ztojuzjko21h4buglmp1qw0p', 'I Expo Investigación Estudiantil', '[{"type": "paragraph", "children": [{"bold": true, "text": "¡Estudiantes, esta es su oportunidad para brillar!", "type": "text"}, {"text": " 🌟", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "🎓 El Vicerrectorado de Investigación de la Universidad Nacional del Altiplano los invita a participar en la I Expo Investigación Estudiantil.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "🗓", "type": "text"}, {"bold": true, "text": " Fecha: ", "type": "text"}, {"text": "19 de diciembre", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "📍 ", "type": "text"}, {"bold": true, "text": "Lugar:", "type": "text"}, {"text": " Campus Universitario", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "🔔 ", "type": "text"}, {"bold": true, "text": "¡Las inscripciones están abiertas hasta el 3 de diciembre! ", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "No pierdas la oportunidad de compartir tu trabajo y aprender de los demás. ¡Haz que tu investigación se vea!", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "🎯 Revisa las bases e inscríbete en ", "type": "text"}, {"bold": true, "text": "https://vriunap.pe/cursos/", "type": "text", "italic": true}]}, {"type": "paragraph", "children": [{"text": " o escanea el QR para más información.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"bold": true, "text": "Organiza: Instituto de Investigación – VRI | Universidad Nacional del Altiplano", "type": "text", "italic": true}]}]', '2025-12-19 05:00:00.000000', 'https://vriunap.pe/cursos/', 'https://vriunap.pe/cursos/', 'Investigación', 'Finalizado', '#investigaciónestudiantil #vriunap #UNAP #innovación #investigacióncientífica', '2026-04-27 17:10:45.689000', '2026-08-07 14:05:55.501000', '2026-08-07 14:05:55.527000', 7, 1, NULL, 'Instituto de Investigacion', NULL),
	(87, 'wcl7u3gbhourt6ff98mdb1eq', 'Concurso Póster Científico ', '[{"type": "paragraph", "children": [{"text": "🧠✨ ", "type": "text"}, {"bold": true, "text": "¡Tu investigación merece ser vista!", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "Participa en el ", "type": "text"}, {"bold": true, "text": "Concurso de Póster Científico UNA Puno 2025", "type": "text"}, {"text": " y demuestra tu talento en las áreas Biomédicas, Ingenierías o Sociales.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "📍 ", "type": "text"}, {"bold": true, "text": "Dirigido a estudiantes de pregrado y semilleros de investigación.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "🎯 Revisa las bases e inscríbete en ", "type": "text"}, {"url": "https://vriunap.pe/cursos/", "type": "link", "children": [{"bold": true, "text": "https://vriunap.pe/cursos/", "type": "text", "italic": true}]}, {"text": " o mas Informes en Instituto de Investigación ", "type": "text"}, {"text": "(Edificio VRI, segundo piso)", "type": "text", "italic": true}]}]', '2025-12-18 13:00:00.000000', 'https://vriunap.pe/cursos/', 'https://vriunap.pe/cursos/', 'Investigación', 'Finalizado', '#UNAInvestiga #VRI #ConcursoCientífico #PunoInvestiga', '2026-04-27 17:23:48.417000', '2026-08-07 14:06:21.580000', '2026-08-07 14:06:21.604000', 7, 1, NULL, 'Instituto de Investigacion', '2025-12-18 05:00:00.000000'),
	(88, 'mfl6smb5cabypehwcg4gclqe', 'III Jornada de Investigación UNA Puno', '[{"type": "paragraph", "children": [{"text": "🚨 ¡", "type": "text"}, {"bold": true, "text": "HOY ES EL ÚLTIMO DÍA", "type": "text"}, {"text": "! 🚨", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "No dejes pasar tu oportunidad de participar en la III Jornada de Investigación – UNA Puno.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"bold": true, "text": "🗓 Del 15 al 19 de diciembre:", "type": "text", "italic": true}]}, {"type": "paragraph", "children": [{"text": "📅 ", "type": "text"}, {"bold": true, "text": "15-16 dic", "type": "text"}, {"text": ":", "type": "text"}, {"bold": true, "text": " III Congreso de Iniciación Científica", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "📅 ", "type": "text"}, {"bold": true, "text": "17 dic", "type": "text"}, {"text": ":", "type": "text"}, {"bold": true, "text": " Concurso “Mi Proyecto de Tesis en un Póster”", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "📅 ", "type": "text"}, {"bold": true, "text": "18 dic: Concurso Póster Científico UNA Puno", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "📅 ", "type": "text"}, {"bold": true, "text": "19 dic: I Expo Investigación Estudiantil", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "🏆 Premios para los mejores proyectos, 📜 certificación de asistencia y 💡 la chance de compartir tus ideas con toda la comunidad estudiantil.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "📝 Inscríbete AHORA antes de que cierren las inscripciones.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "📲 Escanea el QR y sé parte del cambio con tus ideas.", "type": "text"}]}]', '2025-11-19 05:00:00.000000', 'https://vriunap.pe/cursos/', NULL, NULL, 'Proximamente', NULL, '2026-04-27 20:38:10.276000', '2026-08-07 14:06:54.604000', '2026-08-07 14:06:54.623000', 7, 1, NULL, 'Instituto de Investigacion', NULL),
	(89, 'qi3cf5o16333vjacb8fx8vr5', 'Mi Proyecto de Tesis en un Póster ', '[{"type": "paragraph", "children": [{"bold": true, "text": "Tu investigación merece ser vista. ", "type": "text"}, {"text": "💡✨", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "El Instituto de Investigación de la UNA Puno te invita a participar en ", "type": "text"}, {"bold": true, "text": "“Mi Proyecto de Tesis en un Póster”", "type": "text", "italic": true}, {"text": ", una oportunidad para mostrar tu trabajo y destacar tu talento.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"bold": true, "text": "📝 Inscripciones abiertas hasta el 17 de noviembre", "type": "text", "italic": true}]}, {"type": "paragraph", "children": [{"bold": true, "text": "🏆 Premiación a los tres mejores proyectos", "type": "text", "italic": true}]}, {"type": "paragraph", "children": [{"bold": true, "text": "📌 Áreas: Ingenierías, Biomédicas y Sociales", "type": "text", "italic": true}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "Ingresa a 👉", "type": "text"}, {"bold": true, "text": " ", "type": "text", "italic": true}, {"url": "https://vriunap.pe/cursos/", "type": "link", "children": [{"bold": true, "text": "vriunap.pe/cursos", "type": "text", "italic": true}]}, {"text": " y únete.", "type": "text"}]}]', '2025-11-17 05:00:00.000000', 'vriunap.pe/cursos', 'vriunap.pe/cursos', 'Investigación', 'Finalizado', NULL, '2026-04-27 17:15:32.410000', '2026-08-07 14:07:18.430000', '2026-08-07 14:07:18.450000', 7, 1, NULL, 'Instituto de Investigacion', NULL),
	(90, 'ym59fxb73vidcy2dkj6idzdv', 'III Congreso de Iniciación Científica', '[{"type": "paragraph", "children": [{"text": "📢 ", "type": "text"}, {"bold": true, "text": "¡Atención a todos los estudiantes y docentes!", "type": "text"}, {"text": " 📢", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "🎓 Únete al III Congreso de Iniciación Científica", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "🔬 Podrás ser parte de este evento, con la participación de docentes RENACYT y estudiantes de pregrado. Además, se otorgarán premios a los primeros lugares en las áreas de:", "type": "text"}]}, {"type": "paragraph", "children": [{"bold": true, "text": "🛠 Ingeniería", "type": "text", "italic": true}]}, {"type": "paragraph", "children": [{"bold": true, "text": "🧬 Biomédicas", "type": "text", "italic": true}]}, {"type": "paragraph", "children": [{"bold": true, "text": "📚 Sociales", "type": "text", "italic": true}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "💡 Inscripciones abiertas hasta el 14 de noviembre.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "🎯 Revisa las bases e inscríbete en ", "type": "text"}, {"url": "https://vriunap.pe/cursos/", "type": "link", "children": [{"bold": true, "text": "https://vriunap.pe/cursos/", "type": "text", "italic": true}]}, {"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "🏢 Para más información, visita el Instituto de Investigación (Edificio VRI, segundo piso).", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"bold": true, "text": "¡No te lo puedes perder!", "type": "text", "italic": true}, {"text": " 🌟", "type": "text"}]}]', '2025-11-14 05:00:00.000000', 'https://vriunap.pe/cursos/', 'https://vriunap.pe/cursos/', 'Investigación', 'Finalizado', NULL, '2026-04-27 18:44:07.339000', '2026-08-07 14:07:46.558000', '2026-08-07 14:07:46.587000', 7, 1, NULL, 'Instituto de Investigacion', NULL),
	(91, 'snku5bf4q0zq5eox0y04ewsq', 'Capacitación de Desarrollo del Proyecto de Borrador de Tesis de Pregrado en la Plataforma PGI', '[{"type": "paragraph", "children": [{"bold": true, "text": "Convocatoria a Capacitación: Desarrollo del Proyecto y Borrador de Tesis de Pregrado en la Plataforma PGI ", "type": "text"}, {"text": "🔹", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "La Universidad Nacional del Altiplano, a través del Vicerrectorado de Investigación, se complace en invitar a todos los estudiantes de pregrado a la capacitación sobre el desarrollo de proyectos y la elaboración del borrador de tesis, utilizando la Plataforma de Gestión de la Investigación (PGI).", "type": "text"}]}, {"type": "paragraph", "children": [{"bold": true, "text": "", "type": "text", "italic": true}]}, {"type": "paragraph", "children": [{"bold": true, "text": "📅 Fecha: ", "type": "text", "italic": true}, {"text": "Viernes, 07 de noviembre", "type": "text", "italic": true}]}, {"type": "paragraph", "children": [{"bold": true, "text": "⏰ Hora: ", "type": "text", "italic": true}, {"text": "9:00 A.M.", "type": "text", "italic": true}]}, {"type": "paragraph", "children": [{"bold": true, "text": "📍 Modalidad: ", "type": "text", "italic": true}, {"text": "Virtual, a través de Google Meet", "type": "text", "italic": true}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "Esta capacitación tiene como objetivo proporcionar herramientas y orientación para el uso efectivo de la plataforma PGI en la elaboración de proyectos de investigación y la estructuración del borrador de tesis.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "🔗 Para participar, acceda al evento virtual a través del siguiente QR o enlace: ", "type": "text"}, {"url": "https://meet.google.com/qzu-mtht-xup", "type": "link", "children": [{"bold": true, "text": "https://meet.google.com/qzu-mtht-xup", "type": "text", "italic": true}]}, {"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"bold": true, "text": "Esperamos contar con su participación.", "type": "text", "italic": true}]}]', '2025-11-07 14:00:00.000000', NULL, NULL, 'Capacitación', 'Finalizado', '#Capacitación #DesarrolloDeTesis #Investigación #PlataformaPGI #VicerrectoradoDeInvestigación #UNAP', '2026-04-28 14:06:56.784000', '2026-08-07 14:08:10.784000', '2026-08-07 14:08:10.803000', 7, 1, NULL, 'Instituto de Investigacion', '2025-11-07 05:00:00.000000'),
	(92, 'ksnbg1uysl571ol7ipnp6owu', 'Proceso Editorial de una Revista Científica para Indizarse en una Base de Datos', '[{"type": "paragraph", "children": [{"text": "📚", "type": "text"}, {"bold": true, "text": "✨ ¿Quieres que tu revista científica sea indizada en una base de datos?", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "El Instituto de Investigación te invita a la capacitación:", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "🔹", "type": "text"}, {"bold": true, "text": " Proceso editorial de una revista científica para indizarse en una base de datos", "type": "text", "italic": true}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "👨‍🏫", "type": "text"}, {"bold": true, "text": " Ponente", "type": "text"}, {"text": ": Ing. Fernando Ricardo Ardito Saenz", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "📅", "type": "text"}, {"bold": true, "text": " Fecha:", "type": "text"}, {"text": " 14 de octubre", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "⏰ ", "type": "text"}, {"bold": true, "text": "Horario", "type": "text"}, {"text": ": 3:00 – 6:00 p.m.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "📍 ", "type": "text"}, {"bold": true, "text": "Lugar:", "type": "text"}, {"text": " Auditorio de Ciencias Contables UNA-Puno (Pabellón antiguo)", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"bold": true, "text": "✅ Certificación con 100% de asistencia.", "type": "text"}]}, {"type": "paragraph", "children": [{"bold": true, "text": "✅ Ingreso libre.", "type": "text"}]}]', '2025-10-14 20:00:00.000000', NULL, NULL, 'Investigación', 'Finalizado', '#UNA #UNA_Investigación', '2026-04-28 15:04:13.836000', '2026-08-07 14:08:43.638000', '2026-08-07 14:08:43.658000', 7, 1, NULL, 'Instituto de Investigacion', NULL),
	(93, 'it3mc30gfq9r0n8ub93ubiay', 'III Congreso Internacional de Investigación', '[{"type": "paragraph", "children": [{"bold": true, "text": "🔬✨ La ciencia nos une", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "Desde el Vicerrectorado de Investigación de la Universidad Nacional del Altiplano de Puno, invitamos a la comunidad académica y al público en general al III Congreso Internacional de Investigación.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"bold": true, "text": "🗓️ 13 al 15 de octubre de 2025", "type": "text", "italic": true}]}, {"type": "paragraph", "children": [{"bold": true, "text": "📍 Modalidad presencial – UNA Puno", "type": "text", "italic": true}]}, {"type": "paragraph", "children": [{"bold": true, "text": "✅ Se entregará certificación", "type": "text", "italic": true}]}, {"type": "paragraph", "children": [{"bold": true, "text": "📑 Inscripciones abiertas hasta el 10 de octubre", "type": "text", "italic": true}]}, {"type": "paragraph", "children": [{"bold": true, "text": "📑", "type": "text", "italic": true}, {"url": "https://vriunap.pe/cursos/", "type": "link", "children": [{"bold": true, "text": " vriunap.pe/cursos", "type": "text", "italic": true}]}, {"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "👉 ¡Sé parte de este gran encuentro académico con ponentes de Perú, Brasil y Costa Rica! ", "type": "text"}]}]', '2025-10-13 05:00:00.000000', 'https://vriunap.pe/cursos/', NULL, 'Investigación', 'Finalizado', NULL, '2026-05-05 14:29:13.005000', '2026-08-07 14:09:11.418000', '2026-08-07 14:09:11.436000', 7, 1, NULL, 'Instituto de Investigacion', NULL);
