	(257, 'ra5svofhtmxj6vk8vk8qfqmt', 'INSTITUTO DE INVESTIGACIÓN EN TECNOLOGIAS DE INFORMACIÓN Y COMUNICACIÓN ALTO ANDINO - ITICA', 'M.SC. MAGALI GIANINA GONZALES PACO', '2025', '2026-04-28 16:32:43.175000', '2026-04-28 16:32:43.175000', NULL, NULL, NULL, NULL, 'Ingeniería Mecanica Electrica, Electronica y Sistemas', '- Ingeniería de Sistemas', NULL, NULL),
