	(263, 'trr6r1evjihk656185kkipdm', 'INSTITUTO DE INVESTIGACIÓN DEL ALTIPLANO - IIA', 'DR. POLAN BRANBALT FERRO GONZALES', '2025', '2026-04-28 16:32:46.793000', '2026-04-28 16:32:46.793000', NULL, NULL, NULL, NULL, 'Escuela de Posgrado', '- Escuela de Posgrado de la Universidad Nacional del Altiplano', NULL, NULL),
