	(267, 'xntzlcen1f61gf7irqe8y1b7', 'INSTITUTO DE INVESTIGACIÓN EN CIENCIA Y TECNOLOGIA DEL AGUA (IICTA)', 'DR. JOSE ANTONIO MAMANI GOMEZ', '2025', '2026-04-28 16:32:48.584000', '2026-04-28 16:32:48.584000', NULL, NULL, NULL, NULL, 'Ingeniería Agrícola', '- Ingeniería Agrícola', NULL, NULL),
	(268, 'xntzlcen1f61gf7irqe8y1b7', 'INSTITUTO DE INVESTIGACIÓN EN CIENCIA Y TECNOLOGIA DEL AGUA (IICTA)', 'DR. JOSE ANTONIO MAMANI GOMEZ', '2025', '2026-04-28 16:32:48.584000', '2026-04-28 16:32:48.584000', '2026-04-28 16:32:48.589000', NULL, NULL, NULL, 'Ingeniería Agrícola', '- Ingeniería Agrícola', NULL, NULL),
	(273, 'wak4mo4uiyd7sa7735vq5mmr', 'INSTITUTO DE INVESTIGACIÓN EN GEOMÁTICA APLICADA, GEOTECNOLOGIAS ESPACIALES Y TERRESTRES (IGEOMAGET)', 'DR. ELMER ELIO CALIZAYA LLATASI', '2025', '2026-04-28 16:32:52.108000', '2026-04-28 16:32:52.108000', NULL, NULL, NULL, NULL, 'Ciencias  Agrarias', '- Escuela Profesional de Topografía y Agrimensura', NULL, NULL),
