INSERT INTO `noticias` (`id`, `document_id`, `titulo`, `categoria`, `fecha`, `contenido`, `video_url`, `resumen`, `created_at`, `updated_at`, `published_at`, `created_by_id`, `updated_by_id`, `locale`, `direccion`) VALUES
	(14, 'gt2bppi8riweyzru4oemrbo4', 'Clausura de Póster Científico y Mi Proyecto de Tesis en un Póster', NULL, '2025-12-18', '[{"type": "paragraph", "children": [{"text": "Con la participación de más de 70 estudiantes de las diferentes escuelas profesionales de Ingenierías, Ciencias Sociales y Biomédicas, el Vicerrectorado de Investigación de la Universidad Nacional del Altiplano Puno clausuró con éxito el Concurso Póster Científico y “Mi Proyecto de Tesis en un Póster”, desarrollado los días 17 y 18 de diciembre, en una intensa jornada académica de exposiciones e intercambio de conocimientos.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "Esta actividad fue organizada por el ", "type": "text"}, {"url": "https://www.facebook.com/profile.php?id=61552034411617", "type": "link", "children": [{"bold": true, "text": "Instituto de Investigación UNA-Puno", "type": "text", "italic": true}]}, {"text": ", a cargo del Dr. Israel Lima Medina, quien destacó que estas acciones forman parte de una agenda continua de actividades académicas que se vienen desarrollando durante toda la semana, con el firme objetivo de fortalecer la investigación formativa en los estudiantes de pregrado.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "El Vicerrector de Investigación, Dr. Ariel Velazco Cárdenas, resaltó que este tipo de eventos reflejan el compromiso permanente del Vicerrectorado por impulsar y acompañar los procesos de investigación estudiantil, consolidando los semilleros de investigación que vienen obteniendo importantes logros a nivel nacional.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "De esta manera, el Vicerrectorado de Investigación reafirma su compromiso de seguir apoyando y promoviendo espacios académicos que contribuyen al fortalecimiento de la producción científica, posicionando a la UNA Puno como una de las universidades públicas líderes en investigación a nivel nacional.", "type": "text"}]}]', NULL, NULL, '2026-04-27 16:25:38.719000', '2026-08-05 12:09:26.224000', NULL, 7, 7, NULL, 'Instituto de Investigacion');
INSERT INTO `noticias` (`id`, `document_id`, `titulo`, `categoria`, `fecha`, `contenido`, `video_url`, `resumen`, `created_at`, `updated_at`, `published_at`, `created_by_id`, `updated_by_id`, `locale`, `direccion`) VALUES
	(16, 'rdklxk60nbhj8mwgx82c4yfh', 'Inauguración del III Congreso de Iniciación Científica en la UNA Puno', NULL, '2025-12-15', '[{"type": "paragraph", "children": [{"text": "Con el objetivo de fortalecer la investigación formativa y promover la divulgación del conocimiento científico, el Instituto de Investigación del Vicerrectorado de investigación, inauguraron el día 15 de diciembre el III Congreso de Iniciación Científica, evento académico que reúne a docentes y estudiantes investigadores de la comunidad universitaria.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "La ceremonia de inauguración contó con la presencia del Rector, Dr. Paulino Machaca Ari, el Vicerrector Académico, Dr. Mario Cuentas Alvarado, y el Vicerrector de Investigación, Dr. Ariel Velazco Cárdenas, quienes destacaron la importancia de generar espacios que impulsen el desarrollo de competencias científicas en los estudiantes universitarios.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "Durante su intervención, el Rector de la UNA Puno resaltó que este congreso busca fortalecer las capacidades de investigación, comunicación y divulgación científica, permitiendo a los estudiantes generar conocimientos orientados al desarrollo regional y nacional. Asimismo, subrayó que la investigación constituye un pilar fundamental para la formación integral y el progreso sostenible.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "El programa académico del congreso comprende más de 50 conferencias magistrales y ponencias, en las que se presentan proyectos desarrollados por docentes y estudiantes de diversas áreas del conocimiento, consolidando un espacio de diálogo y reflexión académica orientado a la búsqueda de soluciones innovadoras.", "type": "text"}]}]', NULL, NULL, '2026-04-27 16:29:08.610000', '2026-08-05 12:14:44.951000', NULL, 7, 7, NULL, 'Instituto de Investigacion'),
	(18, 's3zmjvck9zq73qmug7830bgs', 'UNA Puno y la Universidad Politécnica de Madrid fortalecen cooperación académica en investigación', NULL, '2025-12-11', '[{"type": "paragraph", "children": [{"text": "El día 11 de diciembre de 2025, de 3:00 p.m. a 7:00 p.m., se llevó a cabo en las instalaciones del Instituto de Investigación del Vicerrectorado de Investigación la jornada inaugural del Curso de Preparación en Competencias para la Formulación y Dirección de Proyectos de Investigación, desarrollado en el marco del Convenio Específico entre el Grupo de Investigación GESPLAN de la Universidad Politécnica de Madrid (UPM) y la Universidad Nacional del Altiplano de Puno (UNA Puno).", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "Este convenio fue suscrito en diciembre de 2024 por el Dr. Fernando Vela Cossío, Secretario General de la UPM y Responsable de Estrategia y Ordenación Académica, y el Dr. Paulino Machaca Ari, Rector de la UNA Puno. Esta colaboración interinstitucional fortalece la formación académica y profesional en la gestión de proyectos de investigación, acercando a la comunidad universitaria a estándares internacionales y la búsqueda de financiamiento de entidades públicas y privadas.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "Las actividades académicas del curso se desarrollarán desde el 10 de diciembre de 2025 hasta el 10 de mayo de 2026, con una duración total de 16 semanas, de acuerdo a lo establecido en el convenio.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "La jornada realizada ayer permitió presentar oficialmente este programa conjunto, reafirmando el compromiso del Vicerrectorado de Investigación con el desarrollo académico, la cooperación internacional y la excelencia en investigación.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"bold": true, "text": " Instituto de Investigación -  Conocimiento científico sin límites", "type": "text", "italic": true}]}, {"type": "paragraph", "children": [{"bold": true, "text": " Vicerrectorado de Investigación", "type": "text", "italic": true}]}, {"type": "paragraph", "children": [{"bold": true, "text": " Universidad Nacional del Altiplano de Puno", "type": "text", "italic": true}]}]', NULL, NULL, '2026-04-27 16:32:45.148000', '2026-08-05 12:20:00.717000', NULL, 7, 7, NULL, 'Instituto de Investigacion'),
	(23, 't4v7l3q59sqqakur1ikdw9yg', 'Inauguración del I Expo Investigación en la Universidad Nacional del Altiplano', NULL, '2025-12-20', '[{"type": "paragraph", "children": [{"text": "El Vicerrectorado de Investigación de la Universidad Nacional del Altiplano Puno, a través de Instituto de Investigación, realizó la I Expo Investigación UNA 2025, actividad desarrollada el viernes 19 de diciembre, siendo la primera experiencia de este tipo organizada en la universidad durante el presente año.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "Esta importante actividad congregó a estudiantes de las áreas de Ingenierías, Ciencias Biomédicas y Ciencias Sociales, quienes no solo presentaron sus pósteres de investigación, sino también avances, prototipos y muestras de los trabajos que vienen desarrollando, permitiendo a la comunidad universitaria conocer de manera más cercana los procesos y enfoques de sus investigaciones.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "El Director de Instituto de Investigación, Dr. Israel Lima Medina, señaló que esta expo es el resultado de una serie de actividades impulsadas por el Vicerrectorado de Investigación. Asimismo, destacó que muchos de los trabajos presentados cuentan con un alto potencial para plasmarse en artículos científicos y procesos de transferencia tecnológica.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "Por su parte, el Vicerrector de Investigación, Dr. Ariel Velazco Cárdenas, resaltó que esta primera expo permite visualizar cómo se viene desarrollando la investigación en cada escuela profesional, brindando a los estudiantes un espacio para socializar los proyectos que vienen registrando y fortalecer sus capacidades de presentación académica, con el acompañamiento de sus docentes.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "En tanto, el Rector de la Universidad Nacional del Altiplano, Dr. Paulino Machaca Ari, destacó que este tipo de eventos contribuyen a que los estudiantes consoliden sus proyectos de tesis en menor tiempo, fomentando además una cultura de participación, felicitando a los estudiantes y escuelas profesionales que vienen destacando en estas iniciativas.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "De esta manera, el Vicerrectorado de Investigación reafirma su compromiso de seguir promoviendo espacios académicos que fortalezcan la investigación formativa y visibilicen los avances científicos desarrollados por la comunidad universitaria.", "type": "text"}]}]', NULL, NULL, '2026-04-27 20:18:17.610000', '2026-08-05 11:56:12.171000', NULL, 7, 7, NULL, 'Instituto de Investigacion'),
	(29, 'xccb9ukcgmhmv1ycksjmhyet', 'Centro Experimental Illpa fortalece su infraestructura agrícola', NULL, '2025-10-23', '[{"type": "paragraph", "children": [{"bold": true, "text": "🌾 Centro Experimental Illpa fortalece su infraestructura agrícola", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "El Vicerrectorado de Investigación continúa promoviendo acciones que consolidan los centros experimentales como espacios estratégicos el desarrollo agropecuario en la región altiplánica.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "En el Centro Experimental Illpa se inauguró la nueva infraestructura del área de maquinaria agrícola, una obra que contribuye al fortalecimiento de las capacidades técnicas y operativas del centro.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "El decano de la Facultad de Ciencias Agrarias, Dr. Javier Mamani Paredes, expresó su satisfacción por este importante avance, destacando el esfuerzo conjunto de las autoridades, trabajadores y personal administrativo que hicieron posible la obra.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "Por su parte, CPC Román Alberto Quispe Alata, administrador del centro experimental, resaltó la importancia del trabajo colaborativo y del compromiso institucional para concretar proyectos que beneficien la formación académica y las actividades de investigación.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "Asimismo, el director del Centro Experimental Illpa, Rony Abel Ciprián Carreón, señaló que esta infraestructura representa un paso más en el fortalecimiento del centro y en el compromiso de seguir impulsando el desarrollo agropecuario en la región.", "type": "text"}]}]', NULL, NULL, '2026-04-28 14:32:58.827000', '2026-08-10 04:16:55.907000', NULL, 7, 1, NULL, 'Direccion de Innovacion y Transferencia Tecnologica'),
	(35, 'pjaha3pjrgpqtyvghdupmd0e', 'Presentación de la Nueva Plataforma de Gestión de la Investigación (PGI)', NULL, '2025-10-23', '[{"type": "paragraph", "children": [{"text": "💻", "type": "text"}, {"bold": true, "text": " PRESENTAN LA NUEVA PLATAFORMA DE GESTIÓN DE LA INVESTIGACIÓN (PGI)", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "El Vicerrectorado de Investigación, a través de Instituto de Investigación, realizó el lanzamiento oficial de la Plataforma de Gestión para la Investigación (PGI), un sistema moderno que unifica todos los servicios y procesos de investigación en nuestra casa superior de estudios.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "🚀 Con esta herramienta digital, se deja atrás la antigua plataforma PILAR, consolidando un solo sistema que beneficiará a más de 20 mil estudiantes y 1,800 docentes, quienes podrán gestionar sus proyectos, tesis y sustentaciones de forma ágil y segura.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "El Vicerrector de Investigación, Dr. Ariel Velazco Cárdenas, destacó que esta innovación responde al compromiso de la gestión universitaria por modernizar la investigación y brindar servicios eficientes a la comunidad académica.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "Por su parte, el Rector, Dr. Paulino Machaca Ari, señaló que con la PGI la UNA Puno ingresa a la era de la transformación digital, permitiendo incluso que, en un futuro cercano, se emitan títulos profesionales digitales en línea y en tiempo real, tal como ocurre en universidades líderes a nivel mundial.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"bold": true, "text": "✅ Con la PGI podrás:", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "Gestionar tu proyecto de tesis de forma completamente digital.", "type": "text", "italic": true}]}, {"type": "paragraph", "children": [{"text": "Hacer seguimiento en tiempo real a tu progreso.", "type": "text", "italic": true}]}, {"type": "paragraph", "children": [{"text": "Recibir notificaciones automáticas para ti y tu asesor.", "type": "text", "italic": true}]}, {"type": "paragraph", "children": [{"text": "Contar con reportes integrados y estadísticas generales.", "type": "text", "italic": true}]}, {"type": "paragraph", "children": [{"text": "Disfrutar de mayor transparencia, seguridad y eficiencia con acceso unificado (Single Sign-On).", "type": "text", "italic": true}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "🌐 ", "type": "text"}, {"bold": true, "text": "UNA Puno avanza hacia la innovación y la internacionalización.", "type": "text"}]}]', NULL, NULL, '2026-04-28 14:45:18.685000', '2026-08-10 04:16:27.152000', NULL, 7, 1, NULL, 'Instituto de Investigacion'),
	(38, 'jbskj4n8vwlvipl7o60xaoir', ' La UNA Puno fortalece el diálogo científico en el Altiplano', NULL, '2025-10-16', '[{"type": "paragraph", "children": [{"text": "Del 13 al 15 de octubre, Instituto de Investigación del Vicerrectorado de Investigación (VRI) desarrolló con éxito el", "type": "text"}, {"bold": true, "text": " ", "type": "text"}, {"bold": true, "text": "III Congreso Internacional de Investigación – UNA Puno 2025", "type": "text", "italic": true}, {"text": ", que reunió a investigadores, docentes y estudiantes del país y del extranjero, consolidando un espacio clave para el intercambio académico y la difusión del conocimiento científico.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "Durante tres días, el Auditorio Magno fue escenario de ponencias magistrales a cargo de destacados especialistas como la Dra. Luz María Paucar Menacho, Dra. Elizabeth Dávila Maguiña, Dr. Fernando Ardito Sáenz, Dra. Tania María Bayer Da Silva, Dr. Hebert Hernán Soto Gonzales, Dr. Diego Ortega Sanabria y la Dra. Tania Carola Padilla Cáceres, quienes compartieron experiencias sobre inteligencia artificial, propiedad intelectual, biología molecular, ética en investigación y avances tecnológicos en la agricultura.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "Además, se presentaron más de un centenar de trabajos en las áreas de Biomédicas, Ingenierías y Sociales, donde participaron investigadores y estudiantes comprometidos con el desarrollo científico de la región.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "El Dr. Israel Lima Medina, director de Instituto de Investigación, destacó la participación de más de 1200 asistentes, mientras que el Vicerrector de Investigación, Dr. Ariel Velazco Cárdenas, resaltó que este encuentro impulsa “la búsqueda del conocimiento que trascienda en el desarrollo integral de la región Puno”.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "✨ Con esta tercera edición, la UNA Puno reafirma su compromiso con la investigación, la innovación y la formación científica desde el corazón del Altiplano.", "type": "text"}]}]', NULL, NULL, '2026-04-28 14:52:41.083000', '2026-08-10 04:17:27.528000', NULL, 7, 1, NULL, 'Instituto de Investigacion'),
	(40, 'cdy514880s0mm7ylfzupil8z', 'Ponencia “Proceso editorial de una revista científica para indizarse en una base de datos”', NULL, '2025-10-14', '[{"type": "paragraph", "children": [{"text": "📚 El Vicerrectorado de Investigación de la Universidad Nacional del Altiplano de Puno, a través de Instituto de Investigación, desarrolló la ponencia", "type": "text"}, {"bold": true, "text": " “Proceso editorial de una revista científica para indizarse en una base de datos”", "type": "text", "italic": true}, {"text": ", dirigida a editores y miembros de revistas científicas, con el propósito de fortalecer las competencias en gestión editorial y en los procesos de indización en bases de datos científicas.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "📅 La actividad se llevó a cabo el 14 de octubre, de 3:00 p.m. a 6:00 p.m., en el Auditorio de la Facultad de Ciencias Contables de la UNA Puno.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "👨‍🏫 El evento estuvo a cargo del", "type": "text"}, {"bold": true, "text": " Ing. Fernando Ricardo Ardito Sáenz", "type": "text", "italic": true}, {"text": ", especialista con amplia trayectoria en el campo editorial científico, ex jefe de Publicaciones Científicas de la Universidad Peruana Cayetano Heredia (2000–2023), y miembro del Council of Science Editors y de la Asociación Peruana de Editores Científicos. Durante su exposición, compartió su experiencia sobre los procesos de gestión editorial, la importancia del acceso abierto y el uso de herramientas como Scopus, SciELO y OJS, orientadas a fortalecer la visibilidad y calidad de las publicaciones científicas.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "💡 Con esta iniciativa, el Instituto de Investigación reafirma su compromiso con la mejora continua de la producción científica y la promoción de buenas prácticas editoriales en las revistas académicas de la Universidad Nacional del Altiplano de Puno, contribuyendo al desarrollo académico y científico de la institución.", "type": "text"}]}]', NULL, NULL, '2026-04-28 14:56:38.289000', '2026-08-10 04:17:52.331000', NULL, 7, 1, NULL, 'Instituto de Investigacion'),
	(42, 'c9gmrmr984eabvjx4c0rbj0q', ' III Congreso Internacional de Investigación – UNA Puno', NULL, '2025-10-13', '[{"type": "paragraph", "children": [{"text": "El Vicerrectorado de Investigación, a través de Instituto de Investigación, inauguró el III Congreso Internacional de Investigación, un evento académico que reúne más de 150 ponencias de investigadores nacionales e internacionales. 🌎📖", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "Durante la ceremonia inaugural, el Rector de la Universidad Nacional del Altiplano, Dr. Paulino Machaca Ari, resaltó la importancia de este tipo de espacios para la comunidad universitaria, especialmente para la formación de los estudiantes. “La investigación es una de las funciones esenciales de la universidad; a través de ella generamos nuevos conocimientos que aportan al desarrollo de la sociedad”, enfatizó.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "El Vicerrector de Investigación, Dr. Ariel Velazco Cárdenas, destacó que este evento consolida el compromiso institucional con la producción científica, mientras que el Dr. Israel Lima Medina, director de la Dirección de Institutos de Investigación, subrayó que este congreso se realiza por tercer año consecutivo, reafirmando la apuesta por la investigación y la innovación, incluso frente a los desafíos que implica la falta de recursos.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "🔬 Con esta nueva edición, Instituto de Investigación reafirma su compromiso con la promoción científica, la innovación y el desarrollo del conocimiento al servicio del progreso regional y nacional.", "type": "text"}]}]', NULL, NULL, '2026-04-28 15:00:45.712000', '2026-08-10 04:18:15.921000', NULL, 7, 1, NULL, 'Instituto de Investigacion'),
	(44, 'do0pdzcinxr98ivhunwj8mx6', 'Ganadores HACKATON CONASEIN 2025', NULL, '2025-09-26', '[{"type": "paragraph", "children": [{"text": "El equipo multidisciplinario de semilleros de nuestra Universidad Nacional del Altiplano se alzó con el primer lugar en la ", "type": "text"}, {"bold": true, "text": "HACKATON del III Congreso Nacional de Semilleros de Investigación – CONASEIN 2025.", "type": "text", "italic": true}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "Este logro destaca el talento y la capacidad innovadora de nuestros estudiantes, quienes trabajaron en colaboración para desarrollar una solución creativa que impresionó al jurado evaluador.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "👏", "type": "text"}, {"bold": true, "text": " ¡Felicitaciones al equipo ganador! Orgullo para toda la comunidad universitaria.", "type": "text"}]}]', NULL, NULL, '2026-04-28 15:38:27.140000', '2026-08-10 04:18:43.725000', NULL, 7, 1, NULL, 'Instituto de Investigacion'),
	(48, 'yyk6ivjwxf1twus4lqp9tvd0', 'CONASEIN 2025', NULL, '2025-09-26', '[{"type": "paragraph", "children": [{"text": "Tras un riguroso proceso de selección nacional, 14 equipos de semilleros de la Universidad Nacional del Altiplano participan exitosamente en el III Congreso Nacional de Semilleros de Investigación – CONASEIN 2025, organizado por la Universidad Nacional del Centro del Perú, Huancayo que se desarrolla del 24, 25 y 26 de septiembre del 2025.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "Estudiantes guiados por docentes investigadores y acompañados por el Dr. Ariel Velazco Cárdenas, Vicerrector de Investigación,  presentaron los resultados de sus trabajos de investigación, representando a nuestra casa de estudios en este importante evento académico nacional.", "type": "text"}]}]', NULL, NULL, '2026-04-28 15:52:25.226000', '2026-08-10 04:18:59.007000', NULL, 7, 1, NULL, 'Instituto de Investigacion'),
	(50, 'qemabi1s0czashzacy9y6z5t', 'II Congreso de Iniciación Científica', NULL, '2024-12-06', '[{"type": "paragraph", "children": [{"text": "📸", "type": "text"}, {"bold": true, "text": " II Congreso de Iniciación Científica", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "Compartimos las postales del", "type": "text"}, {"bold": true, "text": " II Congreso de Iniciación Científica", "type": "text", "italic": true}, {"text": ", resaltando la participación de los estudiantes y ponentes invitados, quienes compartieron con la comunidad universitaria sus importantes investigaciones en diferentes campos de estudio. 📚", "type": "text"}]}]', NULL, NULL, '2026-05-05 14:34:32.245000', '2026-08-10 04:19:45.737000', NULL, 7, 1, NULL, 'Instituto de Investigacion'),
	(58, 'g1d4gvuv3m7czrrwxurb339x', 'DOCENTES EXPONEN EXPERIENCIAS DE SU PASANTÍA INTERNACIONAL', NULL, '2025-09-15', '[{"type": "paragraph", "children": [{"text": "La Universidad Nacional del Altiplano de Puno reafirma su compromiso con la internacionalización académica tras realizar el III Seminario de Socialización de Experiencias de Pasantías Docentes Internacionales 2025-I, organizado por el Vicerrectorado de Investigación a través de la Dirección de Innovación y Transferencia Tecnológica.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "Durante el evento, los docentes socializaron los conocimientos y aprendizajes adquiridos en prestigiosas universidades de Europa, Norteamérica y Sudamérica, luego de un semestre de investigación y capacitación.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "El Rector, Dr. Paulino Machaca Ari, destacó que estas experiencias contribuyen directamente a la formación de los estudiantes y al fortalecimiento de las escuelas profesionales. Asimismo, el Vicerrector de Investigación, Dr. Ariel Velazco Cárdenas, remarcó que esta es la tercera edición consecutiva de una estrategia que impulsa a los docentes a asumir nuevos retos académicos y consolidar redes globales de cooperación.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "En sus palabras de clausura, el director de la Dirección de Innovación y Transferencia Tecnológica, Dr. José Mamani Gomez, señaló que “este seminario inspira a seguir fortaleciendo la cultura investigativa, la innovación y la transferencia de conocimiento en nuestra universidad\\".", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "📚 Estas pasantías, de carácter semestral y permanente, buscan enriquecer la enseñanza con metodologías innovadoras, fomentar proyectos de investigación conjunta y consolidar la cooperación internacional para seguir posicionando a la UNA Puno en el escenario mundial.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "🙌 Felicitamos a nuestros docentes que participaron en esta edición:", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "📚Javier Ruben Romero Cahuana – UNICAMP (Brasil)", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "📚Nina Eleonor Vizcarra Herles – UAM (España)", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "📚Isaac Ticona Zuñiga – UNC (Colombia)", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "📚Flavio Ortiz Calcina – UNC (Colombia)", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "📚Miguel Elías Calcina Benique – USP (Brasil)", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "📚Edwin Guido Boza Condorena – UAM (España)", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "📚Tania Carola Padilla Caceres – UB (España)", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "📚Luz Wilfreda Cusi Zamata – San Francisco State University (EE. UU.)", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "👏 Gracias por compartir sus experiencias y motivarnos a seguir creciendo juntos.", "type": "text"}]}]', NULL, NULL, '2026-05-20 21:06:11.583000', '2026-08-10 04:19:21.683000', NULL, 7, 1, NULL, 'Instituto de Investigacion'),
	(77, 'w3454fu7rvwsypste6rwuftv', 'Universidad Nacional del Altiplano realizó el IV Seminario de Pasantía Docentes 2025 - II', 'Investigación', '2026-04-24', '[{"type": "paragraph", "children": [{"text": "La Universidad Nacional del Altiplano (UNA Puno), a través del Vicerrectorado de Investigación y la Dirección de Innovación y Transferencia Tecnológica, desarrolló con éxito el 𝐈𝐕 𝐒𝐞𝐦𝐢𝐧𝐚𝐫𝐢𝐨 𝐝𝐞 𝐏𝐚𝐬𝐚𝐧𝐭𝐢́𝐚𝐬 𝐃𝐨𝐜𝐞𝐧𝐭𝐞𝐬: Exposición de experiencias de docentes de la pasantía semestral 2025-II, el jueves 23 de abril de 2026, desde las 9:30 a.m., en el Auditorio Magno de la institución.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "El evento tuvo como finalidad **retroalimentar a la comunidad universitaria** mediante el intercambio de experiencias académicas, científicas y formativas de los docentes que participaron en pasantías nacionales e internacionales, en universidades del país y del extranjero.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "Durante la ceremonia de inauguración, el rector de la universidad, Dr. Paulino Machaca Ari, destacó la importancia de estas iniciativas, señalando que es fundamental conocer otras realidades académicas, en un contexto donde el conocimiento es universal y la formación continua resulta clave para el desarrollo profesional.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "Por su parte, el vicerrector de Investigación, Dr. Ariel Velasco Cárdenas, resaltó que estas experiencias permiten fortalecer las capacidades docentes y evidencian que la comunidad académica local puede alcanzar estándares internacionales en investigación y formación.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "A lo largo del seminario, los docentes participantes compartieron sus aprendizajes sobre metodologías de enseñanza, implementación de laboratorios, trabajo en equipos multidisciplinarios y producción científica, reafirmando la importancia de la movilidad académica para mejorar la calidad educativa.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "En ese sentido, el director de la Dirección de Innovación y Transferencia Tecnológica, Dr. José Antonio Mamaní Gómez, enfatizó que las pasantías constituyen una herramienta estratégica para la actualización científica y metodológica, y que los conocimientos adquiridos deben traducirse en proyectos de investigación que contribuyan a la solución de problemáticas regionales y nacionales.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "El evento concluyó con el reconocimiento a los docentes participantes, reafirmando el compromiso institucional de promover la investigación, la innovación y la excelencia académica en beneficio de la comunidad universitaria.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "👏 La universidad reafirma su compromiso con la excelencia académica, la innovación y la investigación.", "type": "text"}]}]', NULL, NULL, '2026-06-16 18:06:05.404000', '2026-08-05 11:44:15.502000', NULL, 1, 7, NULL, 'Direccion de Innovacion y Transferencia Tecnologica'),
	(79, 'n23gl3zyfv5fu16rrtbswynd', 'El IICASB marca un hito en la investigación Q2: Estudio revela la riqueza y diferenciación cultural de la flora medicinal en Capachica y Chucuito', 'Investigación', '2026-06-18', '[{"type": "paragraph", "children": [{"bold": true, "text": "PUNO", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "En un esfuerzo sin precedentes por salvaguardar y validar el conocimiento ancestral del Altiplano, el Instituto de Investigación en Ciencias Ambientales, Salud y Biodiversidad (IICASB) anunció la publicación de un trascendental artículo científico en la prestigiosa revista internacional Phytomedicine Plus. La investigación logra registrar de manera cuantitativa el uso de la flora medicinal en las comunidades Quechua y Aymara que habitan las penínsulas de Capachica y Chucuito, a orillas del Lago Titicaca.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "El estudio, titulado \\"Ethnobotanical evaluation of medicinal flora in Quechua and Aymara communities of the Capachica and Chucuito peninsulas, Lake Titicaca, Peru\\", fue desarrollado por un equipo multidisciplinario liderado por los investigadores Alfredo Loza-Del Carpio, Jesús Miranda-Mamani, Yisela Suaña-Copacondori, Madelyn Melo-Gutierrez, junto a destacados coautores de la región.", "type": "text"}]}, {"type": "paragraph", "children": [{"bold": true, "text": "Ciencia y cultura viva", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "A través de entrevistas a profundidad y la recolección de muestras de herbario, los científicos lograron catalogar un total de 146 especies de plantas medicinales. Uno de los hallazgos más fascinantes de la investigación es que, a pesar de que ambas penínsulas comparten una geografía y una flora muy similar (con una coincidencia botánica del 72.81%), las aplicaciones terapéuticas varían notablemente entre los pobladores quechuas y aymaras. Esta marcada diferencia demuestra cómo cada cultura ha desarrollado su propio sistema de salud y su propia cosmovisión en torno a la naturaleza.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "El análisis estadístico y etnobotánico identificó que plantas nativas como la muña (Clinopodium bolivianum), el paico (Dysphania ambrosioides) y el marco (Ambrosia arborescens) poseen los índices más altos de fidelidad y consenso entre la población para el tratamiento de problemas digestivos y respiratorios, mientras que la Ephedra rupestris destaca en el cuidado del sistema genitourinario.", "type": "text"}]}, {"type": "paragraph", "children": [{"bold": true, "text": "Un puente hacia el futuro de la salud", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "Con este logro en una revista indexada en el prestigioso cuartil Q2, el IICASB no solo eleva el estándar de la producción científica en la región Puno, sino que sienta las bases para futuras investigaciones farmacológicas. Los autores del estudio enfatizan que validar científicamente estas plantas es un paso crucial para lograr, a futuro, una integración formal y respetuosa de la medicina tradicional comunitaria dentro de los sistemas de salud pública contemporáneos.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "La comunidad académica y la población pueden revisar los detalles técnicos y los resultados completos de este orgullo científico regional de manera libre y gratuita bajo la modalidad de acceso abierto a través del identificador digital: ", "type": "text"}, {"url": "https://doi.org/10.1016/j.phyplu.2026.100985", "type": "link", "children": [{"text": "https://doi.org/10.1016/j.phyplu.2026.100985", "type": "text"}]}, {"text": "", "type": "text"}]}]', NULL, 'Una investigación científica liderada por científicos de la región documentó 146 especies de plantas medicinales en las penínsulas de Capachica y Chucuito, logrando una importante publicación indexada en el nivel Q2.', '2026-06-18 19:20:59.591000', '2026-08-07 13:41:31.459000', NULL, 1, 1, NULL, 'Instituto de Investigacion'),
	(83, 'rddhir44yb3cpqowz33mo8h2', 'La UPM y la UNA Puno entregan certificados a docentes investigadores', 'Premiación', '2026-06-23', '[{"type": "paragraph", "children": [{"text": "La UPM y la UNA Puno entregan certificados a docentes investigadores que culminaron satisfactoriamente el curso de Certificación en competencias para la Formulación y Dirección de Proyectos de Investigación", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "El Vicerrectorado de Investigación y el Instituto de Investigación impulsan la excelencia científica internacional 🇵🇪🤝🇪🇸Con gran orgullo institucional, el Vicerrectorado de Investigación, conjuntamente con el Instituto de Investigación, comparten los sobresalientes resultados del curso de \\"Certificación en competencias para la Formulación y Dirección de Proyectos de Investigación\\", desarrollado en un convenio estratégico con el prestigioso grupo GESPLAN de la Universidad Politécnica de Madrid (UPM).  Este programa de alta especialización ha permitido a nuestros docentes e investigadores consolidar sus competencias bajo estándares internacionales.  Como fruto de este esfuerzo conjunto, se han estructurado 6 proyectos de investigación estratégica enfocados en potenciar los indicadores institucionales de nuestra universidad y responder a los desafíos del altiplano:  ", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "• Gestión de la calidad e innovación en la educación universitaria", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "• Impacto de la investigación agropecuaria en el desarrollo rural del altiplano", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "• Identidad digital e internacionalización de la investigación en la UNAP ", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "• Gestión de riesgos en proyectos de investigación financiados en contextos públicos ", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "• Fortalecimiento de grupos de investigación interdisciplinares en la UNAP.  ", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "• Propiedad intelectual y transferencia de conocimiento en la investigación universitaria puneña.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "Desde el Vicerrectorado de Investigación y el Instituto de Investigación, extendemos nuestras más sinceras felicitaciones a cada uno de los profesionales certificados. Su dedicación reafirma el compromiso de la Universidad Nacional del Altiplano con la producción científica de alto impacto. 🎓👏", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "#VRIUNAP #InstitutoDeInvestigación #UNAPuno #InvestigaciónCientífica #UPM #GESPLAN #OrgulloUNAP #Puno", "type": "text"}]}]', NULL, NULL, '2026-06-30 12:35:22.416000', '2026-08-05 11:23:28.814000', NULL, 1, 7, NULL, 'Instituto de Investigacion'),
	(85, 'afn82oa6nkkap3iqgnl4ykbg', 'Resultados de los 50 semilleros de investigación ganadores del Concurso de Financiamiento de Semilleros 2026', 'Resultados', '2026-07-30', '[{"type": "paragraph", "children": [{"text": "La Universidad Nacional del Altiplano (UNA-Puno) dio a conocer los resultados oficiales del Concurso de Semilleros de Investigación 2026, en el que participaron 75 semilleros de 21 escuelas profesionales. Tras la evaluación por puntaje, 50 semilleros fueron declarados ganadores mediante un sistema de distribución proporcional por escuela profesional, garantizando al menos un cupo por cada una.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "El concurso busca fortalecer la formación en investigación científica de los estudiantes de pregrado a través de estos grupos, liderados por docentes responsables, distribuidos en las áreas de Ciencias Sociales, Ciencias de la Ingeniería y Ciencias Biomédicas.", "type": "text"}]}]', NULL, NULL, '2026-07-30 18:38:32.380000', '2026-08-07 13:37:18.145000', NULL, 1, 1, NULL, 'Instituto de Investigacion'),
	(88, 'zz6dicx9dkacmfi797tv1vnc', '📸 Así se vivió "Mi Proyecto de Tesis en un Póster"', 'Investigación', '2026-07-17', '[{"type": "paragraph", "children": [{"text": "Compartimos una galería con los mejores momentos de esta enriquecedora jornada académica, en la que estudiantes de pregrado de la Universidad Nacional del Altiplano presentaron los avances de sus proyectos de tesis mediante pósteres científicos, acercando sus propuestas de investigación a la comunidad.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "Este espacio permitió a los participantes fortalecer sus habilidades para comunicar la ciencia de manera clara y dinámica, recibir valiosas observaciones de docentes y evaluadores, e intercambiar experiencias con otros investigadores en formación. Cada presentación reflejó el compromiso, la creatividad y el esfuerzo de los estudiantes por desarrollar investigaciones que contribuyan a la solución de problemáticas de nuestra región y del país.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "Felicitamos a todos los estudiantes por el trabajo realizado y agradecemos a los docentes, jurados y asistentes por ser parte de esta iniciativa que impulsa la investigación científica y fortalece la formación de los futuros profesionales", "type": "text"}]}]', NULL, NULL, '2026-08-04 15:36:03.830000', '2026-08-05 11:27:45.607000', NULL, 1, 7, NULL, 'Instituto de Investigacion'),
	(90, 'n22utsm23f35xtr9dojz9auo', '📸 Revivimos los mejores momentos del IV Congreso de Iniciación Científica.', 'Investigación', '2026-07-17', '[{"type": "paragraph", "children": [{"text": "Compartimos una galería de imágenes que refleja el entusiasmo, compromiso y participación de estudiantes e investigadores durante el IV Congreso de Iniciación Científica, un espacio dedicado a fortalecer la cultura investigativa y promover el desarrollo de nuevos talentos en la ciencia.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "A lo largo de esta importante jornada académica se llevaron a cabo conferencias magistrales, exposiciones, presentaciones de investigaciones y diversas actividades que fomentaron el intercambio de conocimientos, la innovación y el pensamiento crítico, consolidando a la investigación como un pilar fundamental en la formación universitaria.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "Agradecemos a todos los ponentes, participantes, organizadores y asistentes por contribuir al éxito de este congreso y por seguir impulsando una comunidad académica comprometida con la generación de conocimiento y el desarrollo de nuestra región y del país.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "✨ La investigación es el primer paso para transformar ideas en soluciones que impactan positivamente en la sociedad.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "#IVCongresoDeIniciaciónCientífica #Investigación #Ciencia #Innovación #UniversidadNacionalDelAltiplano #Puno #InvestigaciónUniversitaria #EducaciónSuperior", "type": "text"}]}]', NULL, NULL, '2026-08-04 15:37:54.322000', '2026-08-05 11:33:21.062000', NULL, 1, 7, NULL, 'Instituto de Investigacion'),
	(92, 'xcgpdww96mw6ztz4ps5juzql', '🎓🔬 La investigación llegó a la Plaza Mayor de Puno.', 'Investigación', '2026-07-17', '[{"type": "paragraph", "children": [{"text": "Con gran entusiasmo se desarrolló el evento Póster Científico, una jornada académica en la que estudiantes de pregrado de la Universidad Nacional del Altiplano presentaron los resultados de sus investigaciones a la comunidad.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "Realizado en la Plaza Mayor de la ciudad de Puno, este espacio permitió acercar la ciencia a la población, promoviendo el intercambio de conocimientos y destacando el trabajo investigativo que vienen desarrollando los futuros profesionales en diversas áreas del saber.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "Cada póster representó el esfuerzo, la dedicación y el compromiso de los estudiantes con la generación de conocimiento y la búsqueda de soluciones a problemáticas de interés social, reafirmando el papel fundamental de la investigación en la formación universitaria y en el desarrollo de nuestra región.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "Agradecemos a todos los estudiantes, docentes, jurados y ciudadanos que participaron y contribuyeron al éxito de esta importante actividad, fortaleciendo una cultura de investigación, innovación y divulgación científica.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "✨ Investigar es transformar el conocimiento en oportunidades para la sociedad.", "type": "text"}]}]', NULL, NULL, '2026-08-04 15:40:37.471000', '2026-08-05 11:36:43.447000', NULL, 1, 7, NULL, 'Instituto de Investigacion'),
	(94, 'ttpd6qeeyyo4fpknsdr3tpux', '🎓✨ La innovación y el talento estudiantil fueron los protagonistas de una gran jornada académica en la Universidad Nacional del Altiplano.', 'Investigación', '2026-07-21', '[{"type": "paragraph", "children": [{"text": "El pasado 21 de julio, en la explanada ubicada a las afueras del Rectorado de la Universidad Nacional del Altiplano, estudiantes de las diferentes escuelas profesionales de las facultades participaron en una destacada exposición de proyectos de investigación e innovación, demostrando su creatividad, compromiso y capacidad para generar soluciones a los desafíos de nuestra sociedad.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "Durante el evento se presentaron proyectos correspondientes a las áreas de Ingenierías, Ciencias Sociales y Ciencias Biomédicas, evidenciando el trabajo multidisciplinario y el potencial científico de nuestros futuros profesionales.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "La jornada contó con la participación de evaluadores internacionales, quienes valoraron cada una de las propuestas presentadas, fortaleciendo la calidad académica y promoviendo una cultura de investigación con estándares internacionales.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "👏 Felicitamos a todos los estudiantes, docentes y facultades participantes por hacer posible este importante espacio de intercambio de conocimientos, que reafirma el compromiso de nuestra primera casa de estudios con la investigación, la innovación y la excelencia académica.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "#UniversidadNacionalDelAltiplano #Investigación #Innovación #Ciencia #EstudiantesInvestigadores #Ingenierías #CienciasSociales #CienciasBiomédicas #Puno #UNA", "type": "text"}]}]', NULL, NULL, '2026-08-04 16:40:33.818000', '2026-08-06 15:57:03.076000', NULL, 1, 7, NULL, 'Instituto de Investigacion'),
	(96, 'e4tsi72roysyuy8gw5xkm80r', '🎓🌎 Con gran éxito culminó el IV Congreso Internacional de Investigación de la Universidad Nacional del Altiplano.', 'Investigación', '2026-07-21', '[{"type": "paragraph", "children": [{"text": "Durante los días 20, 21 y 22 de julio, la Universidad Nacional del Altiplano, a través del Vicerrectorado de Investigación y el Instituto de Investigación, llevó a cabo el IV Congreso Internacional de Investigación, un importante espacio académico en el que los docentes investigadores afiliados compartieron los resultados de sus investigaciones, experiencias y aportes científicos con la comunidad universitaria y especialistas nacionales e internacionales.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "A lo largo de las tres jornadas se promovió el intercambio de conocimientos, el fortalecimiento de redes de colaboración y la difusión de investigaciones de alto impacto, reafirmando el compromiso institucional con la generación de conocimiento y la excelencia académica.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "Como acto de cierre, el 22 de julio se realizó la Ceremonia de Clausura, en la que se dio por concluidas las actividades académicas y científicas organizadas por el Vicerrectorado de Investigación, a través del Instituto de Investigación, reconociendo el esfuerzo y la participación de docentes, investigadores, ponentes, evaluadores y asistentes que hicieron posible el éxito de este importante encuentro científico.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "👏 Expresamos nuestro reconocimiento a todos los participantes por contribuir al fortalecimiento de la investigación y la innovación, consolidando a la Universidad Nacional del Altiplano como un referente en la producción científica y el desarrollo del conocimiento.", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "#IVCongresoInternacionalDeInvestigación #UniversidadNacionalDelAltiplano #VicerrectoradoDeInvestigación #InstitutoDeInvestigación #InvestigaciónCientífica #DocentesInvestigadores #Innovación #Ciencia #Puno #ExcelenciaAcadémica", "type": "text"}]}]', NULL, NULL, '2026-08-04 16:45:36.556000', '2026-08-06 15:25:52.594000', NULL, 1, 7, NULL, 'Instituto de Investigacion'),
	(98, 'tel1kybx3e8zkg50png233s9', 'Resultados Oficiales de los 5 eventos organizados por el Instituto de Investigación', 'RESULTADOS', '2026-08-04', '[{"type": "paragraph", "children": [{"text": "🏆 ", "type": "text"}, {"bold": true, "text": "EXPO INVESTIGACIÓN 2026 —  21 de Julio", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "📌 ", "type": "text"}, {"bold": true, "text": "ÁREA BIOMÉDICAS", "type": "text"}]}, {"type": "list", "format": "unordered", "children": [{"type": "list-item", "children": [{"bold": true, "text": "Primer lugar — Escuela Profesional de Medicina Humana", "type": "text", "italic": true}]}]}, {"type": "paragraph", "children": [{"bold": true, "text": "Investigadores:", "type": "text", "italic": true}, {"text": " Álvarez Velásquez Albert Antony, Álvarez Velásquez Leidy Saghura, Apfata Pfoccoalata Anali, Baca Quispe Aitana Libertad", "type": "text"}]}, {"type": "list", "format": "unordered", "children": [{"type": "list-item", "children": [{"bold": true, "text": "Segundo lugar — Escuela Profesional de Medicina Humana", "type": "text", "italic": true}]}]}, {"type": "paragraph", "children": [{"bold": true, "text": "Investigador:", "type": "text", "italic": true}, {"text": " Ulises Mamani, Alexander Canaza", "type": "text"}]}, {"type": "list", "format": "unordered", "children": [{"type": "list-item", "children": [{"bold": true, "text": "Tercer lugar — Escuela Profesional de Odontología", "type": "text", "italic": true}]}]}, {"type": "paragraph", "children": [{"bold": true, "text": "Investigadoras: ", "type": "text", "italic": true}, {"text": "Priscila Nicole Mamani Medina, Mamani Condori Grecia Emeli, Castro Asqui Marilyn Zulma, Condori Huanca Melany Yessenia, Llanos Canaza Fiorela Mischell", "type": "text"}]}, {"type": "paragraph", "children": [{"text": "", "type": "text", "italic": true}]}, {"type": "paragraph", "children": [{"bold": true, "text": "📌 ÁREA INGENIERÍAS", "