INSERT INTO `reglamentos` (`id`, `document_id`, `titulo`, `descripcion`, `tipo`, `created_at`, `updated_at`, `published_at`, `created_by_id`, `updated_by_id`, `locale`) VALUES
	(1, 'js6fa30c2nol6ts3mmwsss0p', 'DIRECTIVA SOBRE PROYECTOS DE INVESTIGACIÓN DOCENTE CON BONIFICACIÓN FEDU', 'La presente Directiva tiene por finalidad establecer los lineamientos, procedimientos y responsabilidades que regulan la formulación, ejecución, seguimiento y cierre de los trabajos\nde Investigación docente beneficiarlos de la bonificación del Fondo Especial de Desarrollo Universitario (FEDU) en la Universidad Nacional del Altiplano de Puno, en adelante\ndenominados Proyectos de Investigación FEDU. Estos proyectos son desarrollados por docentes ordinarios y contratados pertenecientes a los Programas Académicos, al Departamento de Humanidades y a las Secciones que funcionan fuera de la sede central de\nla UNAP.', 'Directiva', '2026-05-05 15:43:36.165000', '2026-08-07 13:52:13.895000', NULL, 7, 1, NULL);
INSERT INTO `reglamentos` (`id`, `document_id`, `titulo`, `descripcion`, `tipo`, `created_at`, `updated_at`, `published_at`, `created_by_id`, `updated_by_id`, `locale`) VALUES
	(4, 'neke2hpv2ajy91c2faljr5om', 'REGLAMENTO DE CREACION Y FUNCIONAMIENTO DE CÍRCULOS DE ESTUDIOS DE LA UNIVERSIDAD NACIONAL DEL ALTIPLANO', 'R.R. 3770-2025-R-UNAP\n\nEI presente reglamento tiene por objeto normar la organización, funcionamiento y actividades de los Círculos de Estudio de la Universidad Nacional del Altiplano, orientados al fortalecimiento académico, la investigación formativa y la innovación entre estudiantes de pregrado.', 'Reglamento', '2026-05-05 15:54:29.906000', '2026-08-07 13:52:30.920000', NULL, 7, 1, NULL),
	(6, 'gxgbyi1aw38ojm8mxw1yjkfi', 'REGLAMENTO DE LICENCIA POR ESTUDIOS Y CAPACITACIÓN OFICIALIZADA', 'RR 3776-2025-R-UNA con REGLAMENTO', 'Reglamento', '2026-05-05 15:58:15.410000', '2026-08-07 13:52:51.529000', NULL, 7, 1, NULL),
	(8, 'f6xdyhk15z75bo3u0x87yu3c', 'REGLAMENTO DE USO DEL SOFTWARE DE CONTROL DE SIMILITUD Y DETECCIÓN DE PLAGIO EN TRABAJOS ACADÉMICOS Y DE INVESTIGACIÓN', 'RR 3777-2025-R-UNA con REGLAMENTO', 'Reglamento', '2026-05-05 16:00:15.591000', '2026-08-07 13:53:50.351000', NULL, 7, 1, NULL),
	(10, 'w520gsgo0tji6ef1ck4bk68p', 'DIRECTIVA DE LOS INSTITUTOS DE INVESTIGACIÓN DE LA UNA-PUNO', 'RR 1916-2025-R-UNA DIRECTIVA INSTITUTOS', 'Directiva', '2026-05-05 16:01:25.490000', '2026-08-07 13:46:35.740000', NULL, 7, 1, NULL),
	(12, 'u6g0zptliy382vcz1xwod1xb', 'REGLAMENTO DE PRESENTACIÓN, DICTAMEN DE BORRADORES Y DEFENSA DE LA TESIS', 'RR 0932-2025-R-UNA con REGLAMENTO BORRADORES', 'Reglamento', '2026-05-05 16:02:40.461000', '2026-08-07 13:53:14.381000', NULL, 7, 1, NULL),
	(14, 'jv2ioew69tlqxx4u01kl4tdw', 'REGLAMENTO DEL REGISTRO, PRESENTACIÓN Y DICTAMEN DE LOS PROYECTOS DE TESIS DE PREGRADO', 'RR 0924-2025-R-UNA con REGLAMENTO PROYECTOS', 'Reglamento', '2026-05-05 16:03:32.317000', '2026-08-07 13:54:58.337000', NULL, 7, 1, NULL),
	(16, 'mylfkxrkv4cwelnwsc2c4xl5', 'REGLAMENTO DEL COMITÉ INSTITUCIONAL DE ÉTICA EN INVESTIGACIÓN DE LA UNIVERSIDAD NACIONAL DEL ALTIPLANO (CIEI)', 'RR 3044-2013-R-UNA REGLAMENTO COMITÉ DE ÉTICA', 'Reglamento', '2026-05-05 16:07:39.770000', '2026-08-07 13:54:38.214000', NULL, 7, 1, NULL),
	(18, 'vmewfi3492zou6u9xcsbniwr', 'REGLAMENTO DELDOCENTE INVESTIGADOR DELA UNIVERSIDAD NACIONAL DEL ALTIPLANO DE PUNO', 'RR 3004-2024-R-UNA con REGLAMENTO docente investigador', 'Reglamento', '2026-05-05 16:09:27.549000', '2026-08-07 13:55:25.768000', NULL, 7, 1, NULL),
