	(22, 'b3ul6n7zf849lq1fb84d7sxa', 'REGLAMENTO DEL COMITÉ DE INTEGRIDAD CIENTIFICA', 'RR 1783-2024-R-UNA con REGLAMENTO integridad', 'Reglamento', '2026-05-05 16:13:57.427000', '2026-08-07 13:54:12.007000', NULL, 7, 1, NULL),
