	(26, 'nfaoqv3diwjf9n1vu71vamgc', 'DIRECTIVA DEL RECONOCIMIENTO Y EVALUACIÓN DE SEMILLEROS DE INVESTIGACIÓN EN LA UNA PUNO', 'RR 1676-2024-R-UNA con DIRECTIVA SEMILLEROS', 'Directiva', '2026-05-05 16:18:41.955000', '2026-08-07 13:51:29.381000', NULL, 7, 1, NULL),
	(28, 'hdtu1kmfy28mfi10xsf1kupg', 'REGLAMENTO DE GESTIÓN DE SUBLÍNEAS DE INVESTIGACIÓN DE LA UNIVERSIDAD NACIONAL DEL ALTIPLANO PUNO', 'R.R. 2187-2023-R-UNA \n\nEl objetivo de las Sublíneas de lnvestigación es facilitar la gestión de la\ninvestigación en los Programas Profesionales, Centros de lnvestigación y\nProducción e lnstitutos de Investigación de la Universidad Nacional del Altiplano -\nPuno.', 'Reglamento', '2026-05-05 16:25:34.269000', '2026-06-01 17:15:44.894000', NULL, 7, 7, NULL),
