	(65, 'i20e231rmyyojhxi67haybzj', 'DIRECTIVA PARA LA CONFORMACION, RECONOCIMIENTO Y EVALUACIÓN DE GRUPOS DE INVESTIGACIÓN EN LA UNA', 'R.R. 1705-2024-R-UNA\n\nFomentar el reconocimiento y desarrollo de los Grupos de Investigación en la Universidad Nacional del Altiplano, como una estrategia para contribuir al desarrollo de la l+D+i en la región Puno.', 'Directiva', '2026-05-05 16:16:18.388000', '2026-08-07 13:51:48.661000', '2026-08-07 13:51:48.679000', 7, 1, NULL),
	(66, 'js6fa30c2nol6ts3mmwsss0p', 'DIRECTIVA SOBRE PROYECTOS DE INVESTIGACIÓN DOCENTE CON BONIFICACIÓN FEDU', 'La presente Directiva tiene por finalidad establecer los lineamientos, procedimientos y responsabilidades que regulan la formulación, ejecución, seguimiento y cierre de los trabajos\nde Investigación docente beneficiarlos de la bonificación del Fondo Especial de Desarrollo Universitario (FEDU) en la Universidad Nacional del Altiplano de Puno, en adelante\ndenominados Proyectos de Investigación FEDU. Estos proyectos son desarrollados por docentes ordinarios y contratados pertenecientes a los Programas Académicos, al Departamento de Humanidades y a las Secciones que funcionan fuera de la sede central de\nla UNAP.', 'Directiva', '2026-05-05 15:43:36.165000', '2026-08-07 13:52:13.895000', '2026-08-07 13:52:13.913000', 7, 1, NULL),
	(67, 'neke2hpv2ajy91c2faljr5om', 'REGLAMENTO DE CREACION Y FUNCIONAMIENTO DE CÍRCULOS DE ESTUDIOS DE LA UNIVERSIDAD NACIONAL DEL ALTIPLANO', 'R.R. 3770-2025-R-UNAP\n\nEI presente reglamento tiene por objeto normar la organización, funcionamiento y actividades de los Círculos de Estudio de la Universidad Nacional del Altiplano, orientados al fortalecimiento académico, la investigación formativa y la innovación entre estudiantes de pregrado.', 'Reglamento', '2026-05-05 15:54:29.906000', '2026-08-07 13:52:30.920000', '2026-08-07 13:52:30.938000', 7, 1, NULL),
	(68, 'gxgbyi1aw38ojm8mxw1yjkfi', 'REGLAMENTO DE LICENCIA POR ESTUDIOS Y CAPACITACIÓN OFICIALIZADA', 'RR 3776-2025-R-UNA con REGLAMENTO', 'Reglamento', '2026-05-05 15:58:15.410000', '2026-08-07 13:52:51.529000', '2026-08-07 13:52:51.546000', 7, 1, NULL),
